  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'post-thyroidectomy priority',
  'management-of-care',
  'case_study',
  '0700: A client returned from a thyroidectomy 90 minutes ago. The dressing is dry. The client is hoarse and now makes a harsh sound on inspiration. Another client is asking for pain medication.',
  'Which client does the nurse see first?',
  '{"options":["The client requesting pain medication","The client with the harsh inspiratory sound","The client whose family is on the phone","The client due for a routine antibiotic at 0900"],"clientNeedsCategory":"Management of Care","blueprintTopic":"post-thyroidectomy priority","kind":"mcq","caseGroupId":"nclex300-thyroid","caseStep":1}',
  'The client with the harsh inspiratory sound',
  'The client with the harsh inspiratory sound fits this step of the case. Stridor after neck surgery is an airway emergency. Incorrect: A pain request, a phone call, and a later antibiotic do not come before airway obstruction.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '85c51bac0b9e4abe09cd643fd164d794259829dc4a63490c89452d47e9d38544',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
