) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  4,
  'reduction-risk',
  'reduction-risk',
  'equipment at the bedside',
  'reduction-risk',
  'case_study',
  '0710: The nurse is with the client who has stridor after thyroidectomy. A coworker asks what must already be at the bedside.',
  'Which equipment is the priority to have ready?',
  '{"options":["A tracheostomy tray and suction","A walker","A heating pad","An incentive spirometer only"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"equipment at the bedside","kind":"mcq","caseGroupId":"nclex300-thyroid","caseStep":2}',
  'A tracheostomy tray and suction',
  'A tracheostomy tray and suction fits this step of the case. Swelling can obstruct the airway and the team may need a surgical airway and suction. Incorrect: A walker, heat, or spirometry does not open an obstructed airway.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '2aa1532ccda9d74f05df38ecc6f52ff0f8223a7f2716047a3e617096ecf42b08',
  'nclex-300-20261108-v1',
  'pending',
  false,
