  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  4,
  'physiological-adaptation',
  'physiological-adaptation',
  'hypocalcemia cue',
  'physiological-adaptation',
  'case_study',
  '0800: The stridor has eased after the rapid response. The client now reports tingling around the mouth and muscle twitching in the hands.',
  'Which laboratory result does the nurse expect to be low?',
  '{"options":["Calcium","Sodium","Glucose","Hemoglobin"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"hypocalcemia cue","kind":"mcq","caseGroupId":"nclex300-thyroid","caseStep":3}',
  'Calcium',
  'Calcium fits this step of the case. Parathyroid glands can be stunned during thyroidectomy, dropping calcium. Incorrect: Sodium, glucose, and hemoglobin do not explain perioral tingling and tetany.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '4346a73e1ed81971f3fce6e27388ea722884f25855b6d98cc423ffa26ebcb508',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
