) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'seizure and tetany precautions',
  'safety-infection',
  'case_study',
  '0810: Calcium is low and the client is twitching. The nurse is setting up the room. The nurse is choosing the safest next action for this client right now.',
  'Which added precaution is appropriate?',
  '{"options":["Padded side rails and seizure precautions","Airborne isolation","A rectal tube","Trendelenburg position"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"seizure and tetany precautions","kind":"mcq","caseGroupId":"nclex300-thyroid","caseStep":4}',
  'Padded side rails and seizure precautions',
  'Padded side rails and seizure precautions fits this step of the case. Severe hypocalcemia can cause seizures. The bed is made safe while calcium is replaced. Incorrect: Isolation, a rectal tube, and Trendelenburg do not address tetany.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '7e281a0ee2c08606051d3c747bdc05bbb9ab972fe8744000736870901ebb5d92',
  'nclex-300-20261108-v1',
  'pending',
  false,
