  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  5,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'calcium replacement',
  'pharmacology-nursing',
  'case_study',
  '0820: IV calcium is ordered. The client is on a cardiac monitor. The nurse is about to give the dose.',
  'Which action is required while calcium is infused?',
  '{"options":["Give it as a rapid IV push without a monitor","Infuse it slowly on a cardiac monitor and stop for bradycardia or a sudden rhythm change","Mix it in the same line as bicarbonate","Give it through a feeding tube"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"calcium replacement","kind":"mcq","caseGroupId":"nclex300-thyroid","caseStep":5}',
  'Infuse it slowly on a cardiac monitor and stop for bradycardia or a sudden rhythm change',
  'Infuse it slowly on a cardiac monitor and stop for bradycardia or a sudden rhythm change fits this step of the case. IV calcium can slow the heart and must be given slowly while the rhythm is watched. Incorrect: A fast unmonitored push, a bicarbonate mixture, or a feeding tube is not how IV calcium is given.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '40ed3b53eb16b4942fa64d060eb7f8840eff64044c38b354c7c8e354ea513dbf',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
