) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'family during an emergency',
  'management-of-care',
  'case_study',
  '0830: The client''s adult child arrives and demands a full update in the hallway while the nurse is still titrating the calcium infusion and watching the monitor.',
  'Which action is appropriate?',
  '{"options":["Leave the bedside to give a detailed hallway update","Stay with the client and arrange a short update after the infusion is stable","Tell the child the calcium value in the hallway","Ask assistive personnel to adjust the calcium rate"],"clientNeedsCategory":"Management of Care","blueprintTopic":"family during an emergency","kind":"mcq","caseGroupId":"nclex300-thyroid","caseStep":6}',
  'Stay with the client and arrange a short update after the infusion is stable',
  'Stay with the client and arrange a short update after the infusion is stable fits this step of the case. The unstable client is not left for a hallway conference, and the rate is not delegated. Incorrect: Leaving, announcing a lab in the hall, or delegating the titration breaks safety and privacy.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '4ae8e26c224512f402a51d1198fc6673409f3a634473197e4c1efb24217abc5c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
