  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  5,
  'physiological-adaptation',
  'physiological-adaptation',
  'recognize sepsis',
  'physiological-adaptation',
  'case_study',
  'A client with a urinary catheter has a temperature of 39.2 C, heart rate 124, blood pressure 86/50 after fluids were not yet given, and new confusion.',
  'Which problem does the nurse recognize?',
  '{"options":["Stable infection","Sepsis with hypotension","Anxiety only","Dehydration that can wait until the next lab draw"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"recognize sepsis","kind":"mcq","caseGroupId":"nclex300-sepsis","caseStep":1}',
  'Sepsis with hypotension',
  'Sepsis with hypotension fits this step of the case. Fever, tachycardia, hypotension, and new confusion from a urinary source are sepsis with shock until treated. Incorrect: Calling it stable, anxiety, or a delay misses the time-sensitive bundle.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"Evans L et al. Surviving Sepsis Campaign 2021 adult guidelines. Crit Care Med 2021","url":"https://pubmed.ncbi.nlm.nih.gov/34599691/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '53152bef0ae4db4737062ab790b4ff4d500336096813edcbfa483f67f643e51d',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  5,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'cultures then antibiotic',
  'pharmacology-nursing',
  'case_study',
  'The sepsis bundle is starting. Blood cultures are not drawn. The antibiotic is at the bedside.',
  'Which sequence does the nurse use?',
  '{"options":["Give the antibiotic, then draw cultures if time allows","Draw the cultures immediately, then start the antibiotic","Wait for the culture result before any antibiotic","Start a narrow antibiotic tomorrow"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"cultures then antibiotic","kind":"mcq","caseGroupId":"nclex300-sepsis","caseStep":2}',
  'Draw the cultures immediately, then start the antibiotic',
  'Draw the cultures immediately, then start the antibiotic fits this step of the case. Cultures come immediately before the antibiotic so treatment is not delayed and the culture is not sterilized. Incorrect: Skipping cultures or waiting for results delays or ruins the workup.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Evans L et al. Surviving Sepsis Campaign 2021 adult guidelines. Crit Care Med 2021","url":"https://pubmed.ncbi.nlm.nih.gov/34599691/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'ee56a98596dd88370fae0bb1dbd27716746400b4d772182cea4a1d5fcd84521c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
