  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  4,
  'reduction-risk',
  'reduction-risk',
  'lactate',
  'reduction-risk',
  'case_study',
  'The client with suspected septic shock has not had a lactate measured. Fluids are starting.',
  'Which test does the nurse send now?',
  '{"options":["Lactate","Fasting lipid panel","Thyroid panel","Prostate-specific antigen"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"lactate","kind":"mcq","caseGroupId":"nclex300-sepsis","caseStep":3}',
  'Lactate',
  'Lactate fits this step of the case. Lactate is part of the early sepsis assessment and guides resuscitation. Incorrect: A lipid panel, thyroid test, or PSA does not guide this resuscitation.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"Evans L et al. Surviving Sepsis Campaign 2021 adult guidelines. Crit Care Med 2021","url":"https://pubmed.ncbi.nlm.nih.gov/34599691/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'f4a835a1928a10e74aa5bfcc59d0516c7d8de3a6a6a28d6f8bb9d2d6e5288c6c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  3,
  'basic-care-comfort',
  'basic-care-comfort',
  'fluid resuscitation position',
  'basic-care-comfort',
  'case_study',
  'The hypotensive client is receiving the initial fluid bolus and feels dizzy when the head of the bed is high.',
  'Which position supports perfusion during the bolus?',
  '{"options":["High Fowler''s at 90 degrees","Supine with the legs supported, unless breathing is worse lying flat","Trendelenburg for the rest of the day","Prone"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"fluid resuscitation position","kind":"mcq","caseGroupId":"nclex300-sepsis","caseStep":4}',
  'Supine with the legs supported, unless breathing is worse lying flat',
  'Supine with the legs supported, unless breathing is worse lying flat fits this step of the case. A flat or low position supports blood pressure during fluids if the client can breathe. Incorrect: Sitting straight up, prolonged Trendelenburg, or prone is not the perfusion position here.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"Evans L et al. Surviving Sepsis Campaign 2021 adult guidelines. Crit Care Med 2021","url":"https://pubmed.ncbi.nlm.nih.gov/34599691/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '738e1bcc7fb55700538eb948855030315f0d7968ed4aab0d9f9607cf844c7a99',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'catheter source',
  'safety-infection',
  'case_study',
  'The urinary catheter has been in for 6 days and is the suspected source. The client is improving after fluids and antibiotics. A removal order is written.',
  'Which action does the nurse take?',
  '{"options":["Leave the catheter because it is convenient","Remove the catheter and start a voiding trial","Change the catheter weekly without an order","Irrigate the catheter with tap water"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"catheter source","kind":"mcq","caseGroupId":"nclex300-sepsis","caseStep":5}',
  'Remove the catheter and start a voiding trial',
  'Remove the catheter and start a voiding trial fits this step of the case. An unneeded catheter is removed once it is the source and the client can be trialed. Incorrect: Keeping it for convenience, a casual weekly change, or tap-water irrigation continues infection risk.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '7d61c561f6fd50e597ee4d72d37e99db85cf5bc40f8b59822a887a346b0db527',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
