  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'who stays with the septic client',
  'management-of-care',
  'case_study',
  'The septic client is still on a norepinephrine infusion. A new graduate asks to take the client plus three other unstable clients.',
  'Which assignment does the charge nurse make?',
  '{"options":["Give the new graduate all four unstable clients","Assign the vasopressor client to an experienced RN and limit the rest of that assignment","Assign the vasopressor to assistive personnel","Ask the LPN to titrate the norepinephrine"],"clientNeedsCategory":"Management of Care","blueprintTopic":"who stays with the septic client","kind":"mcq","caseGroupId":"nclex300-sepsis","caseStep":6}',
  'Assign the vasopressor client to an experienced RN and limit the rest of that assignment',
  'Assign the vasopressor client to an experienced RN and limit the rest of that assignment fits this step of the case. A titrated vasopressor needs an experienced RN and a workload that allows monitoring. Incorrect: Four unstable clients, assistive personnel, or an LPN titration is unsafe.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'c4b8ae7caeec22da2710046e9314e26b0b67df49d6e455bca0f04cacec9d8a65',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
