  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  5,
  'safety-infection',
  'safety-infection',
  'fall with anticoagulant',
  'safety-infection',
  'ngn_bowtie',
  'A client on warfarin has an INR of 4.8, new confusion, and a fresh fall with a bruise behind the ear. Blood pressure is 168/96.',
  'Complete the bow-tie: choose one action and two parameters to monitor.',
  '{"options":["Hold warfarin and obtain an urgent head CT","Give the next warfarin dose now","Encourage ambulation without help","Apply a heating pad to the bruise","Level of consciousness","Pupil size and equality","Hourly blood glucose","Bowel sounds"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"fall with anticoagulant","kind":"bow_tie","condition":"Anticoagulated client with a head strike and a high INR","actions":["Hold warfarin and obtain an urgent head CT","Give the next warfarin dose now","Encourage ambulation without help","Apply a heating pad to the bruise"],"monitors":["Level of consciousness","Pupil size and equality","Hourly blood glucose","Bowel sounds"],"actionPickCount":1,"monitorPickCount":2}',
  'Hold warfarin and obtain an urgent head CT,Level of consciousness,Pupil size and equality',
  'Take Hold warfarin and obtain an urgent head CT and watch Level of consciousness and Pupil size and equality. A high INR plus a head strike is intracranial bleeding until imaging says otherwise. Consciousness and pupils are the monitors. Incorrect: Giving more warfarin, unsupervised walking, a heating pad, glucose, and bowel sounds do not evaluate a head bleed.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'c65ff74f02efd8a831f05a9a6929e91a8edcb061a84908fb0d6e4ad59b398217',
  'nclex-300-20261108-v1',
