) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'hypoglycemia on the unit',
  'management-of-care',
  'ngn_bowtie',
  'A client with type 2 diabetes is sweaty, confused, and has a fingerstick glucose of 48 mg/dL. The client can swallow.',
  'Complete the bow-tie: choose one action and two parameters to monitor.',
  '{"options":["Give 15 grams of fast carbohydrate and recheck glucose","Give the scheduled insulin now","Start the client on a regular diet tray only","Have the client walk the hall","Repeat glucose in 15 minutes","Return of orientation","Urine ketones in 24 hours only","Weekly weight"],"clientNeedsCategory":"Management of Care","blueprintTopic":"hypoglycemia on the unit","kind":"bow_tie","condition":"Hypoglycemia in a client who can swallow","actions":["Give 15 grams of fast carbohydrate and recheck glucose","Give the scheduled insulin now","Start the client on a regular diet tray only","Have the client walk the hall"],"monitors":["Repeat glucose in 15 minutes","Return of orientation","Urine ketones in 24 hours only","Weekly weight"],"actionPickCount":1,"monitorPickCount":2}',
  'Give 15 grams of fast carbohydrate and recheck glucose,Repeat glucose in 15 minutes,Return of orientation',
  'Take Give 15 grams of fast carbohydrate and recheck glucose and watch Repeat glucose in 15 minutes and Return of orientation. A client who can swallow gets rapid carbohydrate and a recheck. Orientation confirms the brain is recovering. Incorrect: Insulin, a meal tray alone, walking, delayed ketones, and weekly weight do not treat glucose of 48.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"American Diabetes Association. Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '803c1fc2c3a8068786d1895cd8c827b62f405d1875d48725bdd184b5b5f519be',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
