) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  5,
  'physiological-adaptation',
  'physiological-adaptation',
  'case nclex300-pph',
  'physiological-adaptation',
  'case_study',
  'A client gave birth 30 minutes ago. The uterus is boggy and a pad is soaked with blood in 15 minutes. The client is dizzy.',
  'What is the first nursing action?',
  '{"options":["Massage the fundus and call for help","Send the client to walk","Give a drink of water","Document the bleeding and recheck in an hour"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"case nclex300-pph","kind":"mcq","caseGroupId":"nclex300-pph","caseStep":1}',
  'Massage the fundus and call for help',
  'Massage the fundus and call for help fits this step of the case. A boggy uterus and rapid soaking are postpartum hemorrhage. Fundal massage and help come first. Incorrect: Walking, water, or waiting an hour lets bleeding continue.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '000b41e7a9c7912a492a482722e4b70d72ba02770e72a3fb0850cde21bba95d1',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
