  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  5,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'case nclex300-pph',
  'pharmacology-nursing',
  'case_study',
  'The fundus firms briefly then bogs again. Oxytocin is infusing. The provider adds methylergonovine if the blood pressure allows. The blood pressure is 168/110.',
  'Which decision about methylergonovine is correct?',
  '{"options":["Give it because bleeding outranks blood pressure","Hold methylergonovine and tell the provider the blood pressure is 168/110","Give a double dose","Give it intravenously as a push without checking pressure"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"case nclex300-pph","kind":"mcq","caseGroupId":"nclex300-pph","caseStep":2}',
  'Hold methylergonovine and tell the provider the blood pressure is 168/110',
  'Hold methylergonovine and tell the provider the blood pressure is 168/110 fits this step of the case. Methylergonovine raises blood pressure and is held when the client is already severely hypertensive. Incorrect: Giving it, doubling it, or pushing it without a pressure check can cause a hypertensive crisis.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '5df00f711907457e949798a3544f8e644c6f8506cbd93e16b74e93b7a608e156',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
