) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  4,
  'reduction-risk',
  'reduction-risk',
  'case nclex300-pph',
  'reduction-risk',
  'case_study',
  'The bladder is palpable above the fundus and the client has not voided since birth. The fundus is shifted to the side.',
  'Which action can help the uterus contract?',
  '{"options":["Help the client empty the bladder","Restrict all fluids","Apply a heating pad to the fundus","Give a sedative"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"case nclex300-pph","kind":"mcq","caseGroupId":"nclex300-pph","caseStep":3}',
  'Help the client empty the bladder',
  'Help the client empty the bladder fits this step of the case. A full bladder displaces the uterus and worsens bleeding. Emptying it lets the fundus firm. Incorrect: Fluid restriction, heat, or a sedative does not empty the bladder.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'db444ae3acafd65712a3df8c6046786ad538619ce12808cd5bd905a1fe5dcefd',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
