) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  3,
  'basic-care-comfort',
  'basic-care-comfort',
  'case nclex300-pph',
  'basic-care-comfort',
  'case_study',
  'After the bladder is emptied the client is cold and shaking. Bleeding has slowed. Vital signs are improving.',
  'Which comfort action is appropriate now?',
  '{"options":["Warm blankets and reassurance while monitoring the bleeding","Ice packs on the chest","Trendelenburg for an hour","Nothing by mouth for 24 hours"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"case nclex300-pph","kind":"mcq","caseGroupId":"nclex300-pph","caseStep":4}',
  'Warm blankets and reassurance while monitoring the bleeding',
  'Warm blankets and reassurance while monitoring the bleeding fits this step of the case. Shaking after birth is common once bleeding is controlled. Warmth and continued watching are appropriate. Incorrect: Chest ice, prolonged Trendelenburg, or a day without oral intake is not required.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'c4006d875ee4e3730aaebf10059e7fea4e7bfa8d714184d335268da77a101f53',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
