) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'case nclex300-pph',
  'safety-infection',
  'case_study',
  'The client is going to a procedure room. The pad count shows 800 mL since birth. Two nurses are needed for the transfer.',
  'Which transfer plan is safe?',
  '{"options":["Transfer with oxygen available, a second nurse, and ongoing fundal checks","Send the client alone in a wheelchair","Walk the client to build strength","Delay the count until after the procedure"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"case nclex300-pph","kind":"mcq","caseGroupId":"nclex300-pph","caseStep":5}',
  'Transfer with oxygen available, a second nurse, and ongoing fundal checks',
  'Transfer with oxygen available, a second nurse, and ongoing fundal checks fits this step of the case. Heavy blood loss needs a supported transfer and continued assessment. Incorrect: Sending the client alone, walking, or dropping the pad count misses recurrent hemorrhage.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '3b3131db93f670c20f0fd08d758799b084c3134a7ce0d0a045cc3d30f57d4ab8',
  'nclex-300-20261108-v1',
  'pending',
  false,
