) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'case nclex300-pph',
  'management-of-care',
  'case_study',
  'The partner is filming the soaked pads on a phone and wants to post them. The client is still being resuscitated.',
  'What does the nurse say?',
  '{"options":["Ask them to stop recording and explain that images of care are not for posting","Help them frame the photo","Post it on the unit page","Ignore it until the next shift"],"clientNeedsCategory":"Management of Care","blueprintTopic":"case nclex300-pph","kind":"mcq","caseGroupId":"nclex300-pph","caseStep":6}',
  'Ask them to stop recording and explain that images of care are not for posting',
  'Ask them to stop recording and explain that images of care are not for posting fits this step of the case. Recording and posting care images violates privacy, especially during an emergency. Incorrect: Helping with the photo, posting it, or ignoring it allows a disclosure.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'faf2c98b9c736b7b860f2b1e246f9217ed984eb105962e4ce4382c7739a8892c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
