  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'case nclex300-chest',
  'reduction-risk',
  'case_study',
  'A client with a chest tube for a pneumothorax has tracheal deviation away from the tube side, severe dyspnea, and a blood pressure of 82/48. The tubing is kinked under the client.',
  'What is the first action?',
  '{"options":["Unkink the tubing and stay with the client while getting help","Clamp the tube and leave","Sit the client in a chair across the room","Increase the IV pain medication only"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"case nclex300-chest","kind":"mcq","caseGroupId":"nclex300-chest","caseStep":1}',
  'Unkink the tubing and stay with the client while getting help',
  'Unkink the tubing and stay with the client while getting help fits this step of the case. A kink can recreate a tension pneumothorax. Opening the system and staying for shock is first. Incorrect: Clamping, leaving the client, or only treating pain delays decompression.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '4b3adcc496d4f2444aa494db57a44760408169120d8bb21099f85fb5f7c73757',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  4,
  'basic-care-comfort',
  'basic-care-comfort',
  'case nclex300-chest',
  'basic-care-comfort',
  'case_study',
  'The kink is relieved and breath sounds are returning. The client is anxious and in pain at the insertion site. A PRN analgesic is ordered and blood pressure is now 118/70.',
  'Which comfort action is appropriate?',
  '{"options":["Give the analgesic and coach slow breaths while watching the drainage","Withhold all pain medicine because of the earlier hypotension","Remove the tube to stop the pain","Have the client cough forcefully without supporting the site"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"case nclex300-chest","kind":"mcq","caseGroupId":"nclex300-chest","caseStep":2}',
  'Give the analgesic and coach slow breaths while watching the drainage',
  'Give the analgesic and coach slow breaths while watching the drainage fits this step of the case. Once perfusion is restored, ordered analgesia and supported breathing are appropriate. Incorrect: Withholding all analgesia, pulling the tube, or unsupported hard coughing is not the plan.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'fd97af5154302986175648c6270a042baa982d77cbd470bc671e395a0a0895c3',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
