) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'case nclex300-chest',
  'safety-infection',
  'case_study',
  'The chest tube dressing is loose and the site is open to air at the edge. The tube is still in place and connected.',
  'What does the nurse do?',
  '{"options":["Reinforce or replace the occlusive dressing with sterile technique","Leave the dressing because it is only loose","Pack the site with a dry washcloth","Cut the tube shorter at the bedside"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"case nclex300-chest","kind":"mcq","caseGroupId":"nclex300-chest","caseStep":3}',
  'Reinforce or replace the occlusive dressing with sterile technique',
  'Reinforce or replace the occlusive dressing with sterile technique fits this step of the case. A loose dressing lets air in around the site. It is sealed with sterile technique. Incorrect: Leaving it, a washcloth, or cutting the tube breaks the seal.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'faab96680096978a3d6a641aa108070e6b4859128fc4be4b87cd73027780a913',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
