) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'case nclex300-chest',
  'management-of-care',
  'case_study',
  'The client with the chest tube also needs a walk. Assistive personnel offer to take the client and the drainage system.',
  'Which direction does the nurse give?',
  '{"options":["The nurse assesses readiness and keeps the drainage system below the chest, and may delegate the steady walk only after that","Have assistive personnel tip the system above the chest to make walking easier","Disconnect the tube for the walk","Let the client carry the system at shoulder height"],"clientNeedsCategory":"Management of Care","blueprintTopic":"case nclex300-chest","kind":"mcq","caseGroupId":"nclex300-chest","caseStep":4}',
  'The nurse assesses readiness and keeps the drainage system below the chest, and may delegate the steady walk only after that',
  'The nurse assesses readiness and keeps the drainage system below the chest, and may delegate the steady walk only after that fits this step of the case. The system stays below the chest. The nurse decides if the client is stable enough to walk. Incorrect: Raising, disconnecting, or carrying the system at the shoulder pulls fluid or air the wrong way.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'e211950f47d0a4dfbb4054cc446c73824969743f0a3b0946c46268c566257f91',
  'nclex-300-20261108-v1',
