  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  3,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'case nclex300-chest',
  'pharmacology-nursing',
  'case_study',
  'The client reports pain of 7 out of 10. Morphine is ordered IV. The respiratory rate is 16 and oxygen saturation is 96 percent.',
  'Which action is appropriate?',
  '{"options":["Give the morphine and reassess rate and sedation","Hold it because the rate is under 20","Give a double dose for chest tubes","Give it by mouth from the IV supply"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"case nclex300-chest","kind":"mcq","caseGroupId":"nclex300-chest","caseStep":5}',
  'Give the morphine and reassess rate and sedation',
  'Give the morphine and reassess rate and sedation fits this step of the case. A rate of 16 with a safe saturation allows the ordered dose, followed by reassessment. Incorrect: Holding for a normal rate, doubling the dose, or using the IV drug by mouth is incorrect.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '03b840c0b051c725fc03519a32b50dd1ca159b2ba79615855acedb8564303c2e',
  'nclex-300-20261108-v1',
  'pending',
