) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  4,
  'physiological-adaptation',
  'physiological-adaptation',
  'case nclex300-chest',
  'physiological-adaptation',
  'case_study',
  'Two hours later the water-seal chamber is bubbling continuously and the client is more short of breath.',
  'What does continuous bubbling suggest?',
  '{"options":["An air leak in the system or a persistent pneumothorax that the provider must know about","A normal finding that needs no report","That the suction should be turned to maximum immediately without looking for a leak","That the tube can be removed"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"case nclex300-chest","kind":"mcq","caseGroupId":"nclex300-chest","caseStep":6}',
  'An air leak in the system or a persistent pneumothorax that the provider must know about',
  'An air leak in the system or a persistent pneumothorax that the provider must know about fits this step of the case. Continuous bubbling in the water seal is an air leak until the system and the client are checked. Incorrect: Ignoring it, maxing suction blindly, or pulling the tube misses the leak.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '88c18eb48a86b5f742e1fed471d8ba970c82b5323425e78694cbcff5a79232e0',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
