) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  5,
  'safety-infection',
  'safety-infection',
  'Suspected air embolism after central line remova',
  'safety-infection',
  'ngn_bowtie',
  'A client pulled out a central line and is short of breath with chest pain on one side. Oxygen saturation is 88 percent.',
  'Complete the bow-tie: select one action and two parameters to monitor.',
  '{"options":["Place the client on the left side in Trendelenburg and give oxygen","Have the client sit up and walk","Apply a warm compress and observe","Lower the oxygen to 1 L","Oxygen saturation","Respiratory effort","Hourly urine glucose","Bowel sounds"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"Suspected air embolism after central line remova","kind":"bow_tie","condition":"Suspected air embolism after central line removal","actions":["Place the client on the left side in Trendelenburg and give oxygen","Have the client sit up and walk","Apply a warm compress and observe","Lower the oxygen to 1 L"],"monitors":["Oxygen saturation","Respiratory effort","Hourly urine glucose","Bowel sounds"],"actionPickCount":1,"monitorPickCount":2}',
  'Place the client on the left side in Trendelenburg and give oxygen,Oxygen saturation,Respiratory effort',
  'Take Place the client on the left side in Trendelenburg and give oxygen and watch Oxygen saturation and Respiratory effort. Left-side Trendelenburg and oxygen are the immediate steps for suspected air embolism. Saturation and work of breathing show if it is working. Incorrect: Walking, a warm compress, low oxygen, glucose, and bowel sounds do not trap the air or track breathing.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '5aba3d47cf2d2f1c70e4111bb57812a28f0c66d7dc037544219a4b4732222baa',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
