) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'Possible compartment syndrome',
  'reduction-risk',
  'ngn_bowtie',
  'A client with a new cast has pain of 10 out of 10 and numbness in the toes that is new. The nurse is choosing the safest next action for this client right now.',
  'Complete the bow-tie: select one action and two parameters to monitor.',
  '{"options":["Notify the provider now and prepare to open the cast","Give two extra opioids and recheck in 4 hours","Elevate the leg on five pillows and leave","Apply ice and a tight bandage","Capillary refill of the toes","Ability to move the toes","Daily weight","Skin turgor on the chest"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"Possible compartment syndrome","kind":"bow_tie","condition":"Possible compartment syndrome","actions":["Notify the provider now and prepare to open the cast","Give two extra opioids and recheck in 4 hours","Elevate the leg on five pillows and leave","Apply ice and a tight bandage"],"monitors":["Capillary refill of the toes","Ability to move the toes","Daily weight","Skin turgor on the chest"],"actionPickCount":1,"monitorPickCount":2}',
  'Notify the provider now and prepare to open the cast,Capillary refill of the toes,Ability to move the toes',
  'Take Notify the provider now and prepare to open the cast and watch Capillary refill of the toes and Ability to move the toes. New numbness and severe pain need the cast opened. Distal refill and movement show whether perfusion and nerve function return. Incorrect: More opioid, high elevation alone, a tight bandage, weight, and chest turgor delay or worsen ischemia.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '2a82bf739d779fdbe6447d05c0ff206d65508b36c8e97f5bb1d9ecfd513be869',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
