) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  4,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'Heparin effect above the therapeutic range',
  'pharmacology-nursing',
  'ngn_bowtie',
  'A client on a heparin infusion has an aPTT that is four times the control and new nose bleeding.',
  'Complete the bow-tie: select one action and two parameters to monitor.',
  '{"options":["Stop the infusion and notify the provider","Increase the infusion to stop the bleeding","Give the next bolus now","Switch to an intramuscular injection","Further bleeding","aPTT after the change","Blood glucose","Pupil size"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"Heparin effect above the therapeutic range","kind":"bow_tie","condition":"Heparin effect above the therapeutic range","actions":["Stop the infusion and notify the provider","Increase the infusion to stop the bleeding","Give the next bolus now","Switch to an intramuscular injection"],"monitors":["Further bleeding","aPTT after the change","Blood glucose","Pupil size"],"actionPickCount":1,"monitorPickCount":2}',
  'Stop the infusion and notify the provider,Further bleeding,aPTT after the change',
  'Take Stop the infusion and notify the provider and watch Further bleeding and aPTT after the change. An aPTT far above range with bleeding means the infusion stops. Bleeding and a repeat aPTT show the response. Incorrect: Increasing the dose, a bolus, an intramuscular injection, glucose, and pupils do not reverse excess anticoagulation.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '1fb51ddda747a26f453754ccc1c33b933daba0b2cea11a81c1e887e3496a4213',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
