) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  5,
  'physiological-adaptation',
  'physiological-adaptation',
  'Unstable ventricular tachycardia',
  'physiological-adaptation',
  'ngn_bowtie',
  'A client in ventricular tachycardia with a pulse is dizzy and the blood pressure is 80/50. The defibrillator is in the room.',
  'Complete the bow-tie: select one action and two parameters to monitor.',
  '{"options":["Prepare for immediate synchronized cardioversion and call for help","Give the client water and recheck in 30 minutes","Start chest compressions while the client is still talking","Have the client bear down only and leave","Blood pressure","Level of consciousness","Urine color in 8 hours","Ankle edema"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"Unstable ventricular tachycardia","kind":"bow_tie","condition":"Unstable ventricular tachycardia","actions":["Prepare for immediate synchronized cardioversion and call for help","Give the client water and recheck in 30 minutes","Start chest compressions while the client is still talking","Have the client bear down only and leave"],"monitors":["Blood pressure","Level of consciousness","Urine color in 8 hours","Ankle edema"],"actionPickCount":1,"monitorPickCount":2}',
  'Prepare for immediate synchronized cardioversion and call for help,Blood pressure,Level of consciousness',
  'Take Prepare for immediate synchronized cardioversion and call for help and watch Blood pressure and Level of consciousness. A pulse with hypotension and dizziness is unstable tachycardia and needs cardioversion, not a delay. Incorrect: Water, compressions on a talking client, leaving after a vagal maneuver, urine color, and ankle edema miss the unstable rhythm.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '8a0eb99075657b757045677c6d5d6bfc81bdb1992f045b72917cb45e7163e468',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
