) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  4,
  'basic-care-comfort',
  'basic-care-comfort',
  'Fluid overload',
  'basic-care-comfort',
  'ngn_bowtie',
  'A client with heart failure has crackles, a weight gain of 2 kg overnight, and orthopnea. The nurse is choosing the safest next action for this client right now.',
  'Complete the bow-tie: select one action and two parameters to monitor.',
  '{"options":["Raise the head of the bed and give the prescribed diuretic","Force oral fluids","Lay the client flat","Give a salt tablet","Respiratory rate","Urine output after the diuretic","Pupil response","Grip strength"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"Fluid overload","kind":"bow_tie","condition":"Fluid overload","actions":["Raise the head of the bed and give the prescribed diuretic","Force oral fluids","Lay the client flat","Give a salt tablet"],"monitors":["Respiratory rate","Urine output after the diuretic","Pupil response","Grip strength"],"actionPickCount":1,"monitorPickCount":2}',
  'Raise the head of the bed and give the prescribed diuretic,Respiratory rate,Urine output after the diuretic',
  'Take Raise the head of the bed and give the prescribed diuretic and watch Respiratory rate and Urine output after the diuretic. Upright position and the ordered diuretic treat overload. Breathing and urine output show the effect. Incorrect: Fluids, lying flat, salt, pupils, and grip strength worsen or ignore the fluid.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'b5797f5967035605ec61e03be51516aa6b11646ff20de6bca139ed16d980d052',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
