) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'psychosocial',
  4,
  'psychosocial',
  'psychosocial',
  'Severe alcohol withdrawal',
  'psychosocial',
  'ngn_bowtie',
  'A client in alcohol withdrawal has a CIWA score in the severe range, a tremor, and a heart rate of 130.',
  'Complete the bow-tie: select one action and two parameters to monitor.',
  '{"options":["Give the protocol benzodiazepine and stay with the client","Discharge the client to the waiting room","Offer coffee and a walk","Apply restraints and give no medication","Heart rate","Seizure activity","Weekly weight","Hair loss"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"Severe alcohol withdrawal","kind":"bow_tie","condition":"Severe alcohol withdrawal","actions":["Give the protocol benzodiazepine and stay with the client","Discharge the client to the waiting room","Offer coffee and a walk","Apply restraints and give no medication"],"monitors":["Heart rate","Seizure activity","Weekly weight","Hair loss"],"actionPickCount":1,"monitorPickCount":2}',
  'Give the protocol benzodiazepine and stay with the client,Heart rate,Seizure activity',
  'Take Give the protocol benzodiazepine and stay with the client and watch Heart rate and Seizure activity. Severe withdrawal is treated with a benzodiazepine at the bedside because seizures can follow. Incorrect: Discharge, coffee, restraints without medication, weight, and hair loss do not prevent seizures.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '95eb751b40e6b27ff0a6b4febb35292e10f5737e87ef16c5022bd9a0055c1a67',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
