) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'health-promotion',
  3,
  'health-promotion',
  'health-promotion',
  'Early breastfeeding',
  'health-promotion',
  'ngn_bowtie',
  'A postpartum client wants to breastfeed and the newborn is 2 hours old and rooting. The nurse is choosing the safest next action for this client right now.',
  'Complete the bow-tie: select one action and two parameters to monitor.',
  '{"options":["Help the newborn latch skin to skin now","Give a bottle first so the mother can rest all night","Schedule the first feed for tomorrow","Use a pacifier as the only intake","Audible swallows","Newborn temperature","Maternal cholesterol","Paternal blood type"],"clientNeedsCategory":"Health Promotion and Maintenance","blueprintTopic":"Early breastfeeding","kind":"bow_tie","condition":"Early breastfeeding","actions":["Help the newborn latch skin to skin now","Give a bottle first so the mother can rest all night","Schedule the first feed for tomorrow","Use a pacifier as the only intake"],"monitors":["Audible swallows","Newborn temperature","Maternal cholesterol","Paternal blood type"],"actionPickCount":1,"monitorPickCount":2}',
  'Help the newborn latch skin to skin now,Audible swallows,Newborn temperature',
  'Take Help the newborn latch skin to skin now and watch Audible swallows and Newborn temperature. Early skin-to-skin latch supports feeding and temperature. Swallows show milk transfer. Incorrect: A bottle first, waiting a day, a pacifier as intake, cholesterol, and blood type are not the feeding cues.',
  '["nclex","NCLEX-RN-2026","health-promotion","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Adult immunization schedule. CDC 2026","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/adult-notes.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'd4df274e21373ebad2964128fae46176f66db50fda311e6bf73a70425d9c5d46',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'Early anaphylaxis after a wrong drug',
  'management-of-care',
  'ngn_bowtie',
  'A client with a known anaphylaxis history was just given the wrong antibiotic. Hives and wheezing have started.',
  'Complete the bow-tie: select one action and two parameters to monitor.',
  '{"options":["Stop the drug and give intramuscular epinephrine and and call for help","Finish the infusion because it is almost done","Give diphenhydramine as the only drug","Document and reassess in an hour","Blood pressure","Airway sounds","Daily weight","Stool color"],"clientNeedsCategory":"Management of Care","blueprintTopic":"Early anaphylaxis after a wrong drug","kind":"bow_tie","condition":"Early anaphylaxis after a wrong drug","actions":["Stop the drug and give intramuscular epinephrine and and call for help","Finish the infusion because it is almost done","Give diphenhydramine as the only drug","Document and reassess in an hour"],"monitors":["Blood pressure","Airway sounds","Daily weight","Stool color"],"actionPickCount":1,"monitorPickCount":2}',
  'Stop the drug and give intramuscular epinephrine and and call for help,Blood pressure,Airway sounds',
  'Take Stop the drug and give intramuscular epinephrine and and call for help and watch Blood pressure and Airway sounds. The infusion stops and epinephrine is given. Pressure and airway sounds track shock and swelling. Incorrect: Finishing the drug, an antihistamine alone, waiting, weight, and stool color leave anaphylaxis untreated.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '19162e0f0bd15f0b06135ca3500fd9f62bb1bfcc7b8ec9cc9b98fd728c181bd8',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'matrix classification',
  'safety-infection',
  'ngn_matrix',
  'A nurse is sorting isolation needs for four clients admitted this hour. The nurse is choosing the safest next action for this client right now.',
  'For each finding, select the appropriate category.',
  '{"options":["Client with measles|||Airborne precautions","Client with measles|||Droplet precautions","Client with measles|||Contact precautions","Client with measles|||Standard precautions","Client with influenza|||Airborne precautions","Client with influenza|||Droplet precautions","Client with influenza|||Contact precautions","Client with influenza|||Standard precautions","Client with C. difficile|||Airborne precautions","Client with C. difficile|||Droplet precautions","Client with C. difficile|||Contact precautions","Client with C. difficile|||Standard precautions","Client with a closed fracture and no infection|||Airborne precautions","Client with a closed fracture and no infection|||Droplet precautions","Client with a closed fracture and no infection|||Contact precautions","Client with a closed fracture and no infection|||Standard precautions"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"matrix classification","kind":"matrix","rows":["Client with measles","Client with influenza","Client with C. difficile","Client with a closed fracture and no infection"],"columns":["Airborne precautions","Droplet precautions","Contact precautions","Standard precautions"],"rowHeader":"Finding"}',
  'Client with measles|||Airborne precautions,Client with influenza|||Droplet precautions,Client with C. difficile|||Contact precautions,Client with a closed fracture and no infection|||Standard precautions',
  'Each finding is classified by the action it requires. Each organism has a route, and the fracture without infection does not need transmission precautions. Incorrect: Mixing airborne, droplet, and contact precautions spreads infection or isolates a client who does not need it.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '9f372a8770e0ad3e99ad1aba570333ed6cbaf859f14a696f6484bdd7aa943a57',
  'nclex-300-20261108-v1',
