) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'matrix classification',
  'reduction-risk',
  'ngn_matrix',
  'A client is two hours after abdominal surgery and has four findings at the same time. The nurse must classify each one.',
  'For each finding, select the appropriate category.',
  '{"options":["Oxygen saturation 86 percent|||Intervene now","Oxygen saturation 86 percent|||Expected now","Oxygen saturation 86 percent|||Needs more data","Small serosanguineous spot on the dressing|||Intervene now","Small serosanguineous spot on the dressing|||Expected now","Small serosanguineous spot on the dressing|||Needs more data","New calf swelling and chest pain|||Intervene now","New calf swelling and chest pain|||Expected now","New calf swelling and chest pain|||Needs more data","Dressing soaked with bright red blood in 10 minutes|||Intervene now","Dressing soaked with bright red blood in 10 minutes|||Expected now","Dressing soaked with bright red blood in 10 minutes|||Needs more data"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"matrix classification","kind":"matrix","rows":["Oxygen saturation 86 percent","Small serosanguineous spot on the dressing","New calf swelling and chest pain","Dressing soaked with bright red blood in 10 minutes"],"columns":["Intervene now","Expected now","Needs more data"],"rowHeader":"Finding"}',
  'Oxygen saturation 86 percent|||Intervene now,Small serosanguineous spot on the dressing|||Expected now,New calf swelling and chest pain|||Intervene now,Dressing soaked with bright red blood in 10 minutes|||Intervene now',
  'Hypoxia, signs of embolism, and a rapidly soaking dressing are acted on now. A small serosanguineous spot early after surgery can be expected. Incorrect: treating the small spot as the emergency, or watching the soaking dressing, reverses the priorities.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'e8d4a0098e6b147375962e17e4d99da0e922c861d36d3f224b5f790d759daa22',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
