) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  4,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'matrix classification',
  'pharmacology-nursing',
  'ngn_matrix',
  'A nurse is checking whether each medication situation is safe to give right now. The nurse is choosing the safest next action for this client right now.',
  'For each finding, select the appropriate category.',
  '{"options":["Apical pulse 48 before digoxin|||Hold and notify","Apical pulse 48 before digoxin|||Give as ordered","Potassium 3.0 mEq/L before IV furosemide|||Hold and notify","Potassium 3.0 mEq/L before IV furosemide|||Give as ordered","Pain 8 out of 10 with a due opioid and a respiratory rate of 16|||Hold and notify","Pain 8 out of 10 with a due opioid and a respiratory rate of 16|||Give as ordered","Blood pressure 86/50 before a new antihypertensive|||Hold and notify","Blood pressure 86/50 before a new antihypertensive|||Give as ordered"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"matrix classification","kind":"matrix","rows":["Apical pulse 48 before digoxin","Potassium 3.0 mEq/L before IV furosemide","Pain 8 out of 10 with a due opioid and a respiratory rate of 16","Blood pressure 86/50 before a new antihypertensive"],"columns":["Hold and notify","Give as ordered"],"rowHeader":"Finding"}',
  'Apical pulse 48 before digoxin|||Hold and notify,Potassium 3.0 mEq/L before IV furosemide|||Hold and notify,Pain 8 out of 10 with a due opioid and a respiratory rate of 16|||Give as ordered,Blood pressure 86/50 before a new antihypertensive|||Hold and notify',
  'Each finding is classified by the action it requires. Digoxin at a slow rate, a loop diuretic with severe hypokalemia, and a blood-pressure drug during shock are held. Pain medicine at a safe respiratory rate is given. Incorrect: Giving the held drugs or holding the opioid at a rate of 16 is the unsafe swap.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'f6431d968bc77038354b42b62ee69da205899ace8812687c0b9f10c50fd04efe',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
