) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  4,
  'basic-care-comfort',
  'basic-care-comfort',
  'matrix classification',
  'basic-care-comfort',
  'ngn_matrix',
  'Four clients need a diet decision before the meal tray arrives. Speech therapy has seen only one of them.',
  'For each finding, select the appropriate category.',
  '{"options":["Client who coughed on thin water and has not been cleared by speech therapy|||Nothing by mouth","Client who coughed on thin water and has not been cleared by speech therapy|||Nectar-thick liquids","Client who coughed on thin water and has not been cleared by speech therapy|||Clear thin liquids","Client whose nausea has stopped and who has an order for clear liquids|||Nothing by mouth","Client whose nausea has stopped and who has an order for clear liquids|||Nectar-thick liquids","Client whose nausea has stopped and who has an order for clear liquids|||Clear thin liquids","Client vomiting with a bowel obstruction|||Nothing by mouth","Client vomiting with a bowel obstruction|||Nectar-thick liquids","Client vomiting with a bowel obstruction|||Clear thin liquids","Client cleared by speech therapy for nectar-thick liquids only|||Nothing by mouth","Client cleared by speech therapy for nectar-thick liquids only|||Nectar-thick liquids","Client cleared by speech therapy for nectar-thick liquids only|||Clear thin liquids"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"matrix classification","kind":"matrix","rows":["Client who coughed on thin water and has not been cleared by speech therapy","Client whose nausea has stopped and who has an order for clear liquids","Client vomiting with a bowel obstruction","Client cleared by speech therapy for nectar-thick liquids only"],"columns":["Nothing by mouth","Nectar-thick liquids","Clear thin liquids"],"rowHeader":"Finding"}',
  'Client who coughed on thin water and has not been cleared by speech therapy|||Nothing by mouth,Client whose nausea has stopped and who has an order for clear liquids|||Clear thin liquids,Client vomiting with a bowel obstruction|||Nothing by mouth,Client cleared by speech therapy for nectar-thick liquids only|||Nectar-thick liquids',
  'An uncleared cough on thin liquids and a bowel obstruction stay nothing by mouth. A stopped nausea with a clear-liquid order may have clear thin liquids. The cleared client gets nectar thickness only. Incorrect: nectar liquids for the uncleared client, or any oral intake for the obstruction, risks aspiration.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '122adcdc9d0fab33ab49fad0648f03db5f36e6f60479fbf4f216d846adc7a1f5',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
