) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'psychosocial',
  4,
  'psychosocial',
  'psychosocial',
  'matrix classification',
  'psychosocial',
  'ngn_matrix',
  'A nurse is sorting safety needs for mental health clients. The nurse is choosing the safest next action for this client right now.',
  'For each finding, select the appropriate category.',
  '{"options":["Client with a plan and access to a gun|||One-to-one observation now","Client with a plan and access to a gun|||Routine checks and therapeutic talk","Client with a plan and access to a gun|||De-escalation and a safe space","Client crying about a loss who denies suicidal thoughts|||One-to-one observation now","Client crying about a loss who denies suicidal thoughts|||Routine checks and therapeutic talk","Client crying about a loss who denies suicidal thoughts|||De-escalation and a safe space","Client hearing voices but eating and contracting for safety|||One-to-one observation now","Client hearing voices but eating and contracting for safety|||Routine checks and therapeutic talk","Client hearing voices but eating and contracting for safety|||De-escalation and a safe space","Client pacing and threatening to hit staff|||One-to-one observation now","Client pacing and threatening to hit staff|||Routine checks and therapeutic talk","Client pacing and threatening to hit staff|||De-escalation and a safe space"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"matrix classification","kind":"matrix","rows":["Client with a plan and access to a gun","Client crying about a loss who denies suicidal thoughts","Client hearing voices but eating and contracting for safety","Client pacing and threatening to hit staff"],"columns":["One-to-one observation now","Routine checks and therapeutic talk","De-escalation and a safe space"],"rowHeader":"Finding"}',
  'Client with a plan and access to a gun|||One-to-one observation now,Client crying about a loss who denies suicidal thoughts|||Routine checks and therapeutic talk,Client hearing voices but eating and contracting for safety|||Routine checks and therapeutic talk,Client pacing and threatening to hit staff|||De-escalation and a safe space',
  'Each finding is classified by the action it requires. A plan plus a gun needs constant observation. Grief and contracted voices need presence, not the same emergency watch. A threatening client needs de-escalation first. Incorrect: Using one-to-one for every tear or ignoring the firearm plan is the error.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '413a0bbb891c5aa930e01da4af25b1ee0a9e77a13545e6d86125365f8c8f5a14',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
