  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'matrix classification',
  'management-of-care',
  'ngn_matrix',
  'The charge nurse is sorting which worker may perform each task. The nurse is choosing the safest next action for this client right now.',
  'For each finding, select the appropriate category.',
  '{"options":["Collect a stool sample from a stable client|||Assistive personnel","Collect a stool sample from a stable client|||Registered nurse","Give IV push morphine|||Assistive personnel","Give IV push morphine|||Registered nurse","Teach a new ostomy|||Assistive personnel","Teach a new ostomy|||Registered nurse","Irrigate a new colostomy for the first time|||Assistive personnel","Irrigate a new colostomy for the first time|||Registered nurse"],"clientNeedsCategory":"Management of Care","blueprintTopic":"matrix classification","kind":"matrix","rows":["Collect a stool sample from a stable client","Give IV push morphine","Teach a new ostomy","Irrigate a new colostomy for the first time"],"columns":["Assistive personnel","Registered nurse"],"rowHeader":"Finding"}',
  'Collect a stool sample from a stable client|||Assistive personnel,Give IV push morphine|||Registered nurse,Teach a new ostomy|||Registered nurse,Irrigate a new colostomy for the first time|||Registered nurse',
  'Each finding is classified by the action it requires. A collected specimen from a stable client can be delegated. IV push, first teaching, and a first irrigation stay with the RN. Incorrect: Delegating the IV push or the first teaching gives away nursing judgment.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'b158d8b7ad7fc1a80292dc9da2c7aeabdf8903c29457049d55522f431ae48c3b',
  'nclex-300-20261108-v1',
  'pending',
  false,
