  'nursing',
  'safety-infection',
  3,
  'safety-infection',
  'safety-infection',
  'fire order',
  'safety-infection',
  'ordered_response',
  'The nurse finds a small fire in a wastebasket and a client is in the room. The nurse is choosing the safest next action for this client right now.',
  'Place the actions in the safe order.',
  '{"options":["Pull the alarm","Rescue the client","Confine the fire by closing the door","Extinguish if it is safe"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"fire order","kind":"ordered_response"}',
  'Rescue the client,Pull the alarm,Confine the fire by closing the door,Extinguish if it is safe',
  'The safe order is fixed by the risk, not by the list on the screen. Rescue is first when a person is in the room, then alarm, confine, and extinguish. Incorrect: Alarm before rescue leaves the client in the fire.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'c06bb6e84400fea09b83e38a3f995b57bb39a92c5e91c4d219bdc67176ea25df',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
