) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  5,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'blood culture and antibiotic',
  'pharmacology-nursing',
  'ordered_response',
  'A client in septic shock has no cultures drawn. The antibiotic is at the bedside and has not been started. The nurse is choosing the safest next action for this client right now.',
  'Place the steps in the safe order.',
  '{"options":["Start the antibiotic","Document the time the antibiotic was started","Draw the blood cultures","Confirm two client identifiers"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"blood culture and antibiotic","kind":"ordered_response"}',
  'Confirm two client identifiers,Draw the blood cultures,Start the antibiotic,Document the time the antibiotic was started',
  'Identity is confirmed, cultures are drawn before the antibiotic, the antibiotic is started, and the time is documented. Incorrect: starting the antibiotic before the cultures can sterilize the specimen.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Evans L et al. Surviving Sepsis Campaign 2021 adult guidelines. Crit Care Med 2021","url":"https://pubmed.ncbi.nlm.nih.gov/34599691/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'ffd738e1c477449d51c860311ebb5683f2f0d17f64971fbd1a93689e93620fbd',
  'nclex-300-20261108-v1',
  'pending',
  false,
