  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  4,
  'reduction-risk',
  'reduction-risk',
  'donning protective equipment',
  'reduction-risk',
  'ordered_response',
  'The nurse is entering the room of a client on contact and droplet precautions. The nurse is choosing the safest next action for this client right now.',
  'Place the donning steps in order.',
  '{"options":["Gloves","Gown","Mask","Hand hygiene"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"donning protective equipment","kind":"ordered_response"}',
  'Hand hygiene,Gown,Mask,Gloves',
  'The safe order is fixed by the risk, not by the list on the screen. Hands are cleaned first, then gown and mask, and gloves last so the gloves cover the cuffs. Incorrect: Gloves first contaminate the rest of the equipment.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '409b6b1eadae3756912846a5e6350fdc4dea799dd5c11ba6f2d7519b2999806d',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  5,
  'physiological-adaptation',
  'physiological-adaptation',
  'adult CPR',
  'physiological-adaptation',
  'ordered_response',
  'Help has already been called. An adult client has no pulse and is not breathing. The defibrillator is in the nurse''s hands.',
  'Place the actions in the safe order.',
  '{"options":["Attach the defibrillator and follow its prompts","Resume compressions immediately after the rhythm check","Start chest compressions","Expose the chest"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"adult CPR","kind":"ordered_response"}',
  'Expose the chest,Start chest compressions,Attach the defibrillator and follow its prompts,Resume compressions immediately after the rhythm check',
  'The chest is exposed, compressions start, the defibrillator is attached, and compressions resume right after the rhythm check. Incorrect: breaths or a long pause before compressions delay circulation. The list on the screen is not this order.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '21f418d26a905e6dda62fcd557671361363daa9d9ab15e910dde88119bd17712',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'telephone order',
  'management-of-care',
  'ordered_response',
  'A provider is giving a telephone order for a new opioid. The nurse is choosing the safest next action for this client right now.',
  'Place the safety steps in order.',
  '{"options":["Administer the drug","Write the order","Read the drug and dose and route and and frequency back","Ask the provider to confirm the read-back"],"clientNeedsCategory":"Management of Care","blueprintTopic":"telephone order","kind":"ordered_response"}',
  'Write the order,Read the drug and dose and route and and frequency back,Ask the provider to confirm the read-back,Administer the drug',
  'The safe order is fixed by the risk, not by the list on the screen. The order is written, read back, confirmed, and only then given. Incorrect: Giving the drug before the read-back skips the safety check.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'c2b3305ce3daea93707c57b3ef0b72d793ecdce580b4929414a8bc4dce020b1a',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  5,
  'safety-infection',
  'safety-infection',
  'suicide room hazards',
  'safety-infection',
  'select_all',
  'A client on suicide precautions is moving into a room. The nurse is removing hazards. The nurse is choosing the safest next action for this client right now.',
  'Which items must be removed or locked away? Select all that apply.',
  '{"options":["Trash-can liners","IV tubing not in use","A plastic spoon with a meal tray that staff will observe","A belt left in the closet","The hospital pillowcase"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"suicide room hazards","kind":"select_all"}',
  'Trash-can liners|||IV tubing not in use|||A belt left in the closet',
  'The indicated choices are the ones that change the plan now. Liners, tubing, and a belt can be used for self-harm and are removed. Incorrect: An observed plastic spoon and a pillowcase are not the same class of hazard and are not the items this question is removing.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'ac59d55694b0b7b6e6561d654b819f6bf2495da984879474f3a9001826432cbd',
