) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  4,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'hold parameters',
  'pharmacology-nursing',
  'select_all',
  'A nurse is deciding which findings require holding the drug and calling the provider. The nurse is choosing the safest next action for this client right now.',
  'Which findings require a hold? Select all that apply.',
  '{"options":["Apical pulse 50 before digoxin","Potassium 3.0 before IV furosemide","Respiratory rate 16 before a prescribed opioid","Blood pressure 84/48 before carvedilol","Pain score 7 before a nonopioid analgesic"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"hold parameters","kind":"select_all"}',
  'Apical pulse 50 before digoxin|||Potassium 3.0 before IV furosemide|||Blood pressure 84/48 before carvedilol',
  'The indicated choices are the ones that change the plan now. A slow pulse before digoxin, severe hypokalemia before a loop diuretic, and shock-range pressure before a beta blocker are holds. Incorrect: A respiratory rate of 16 and pain of 7 are not reasons to hold those particular doses.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'a0471352cc8d8ee3b3a9fe76e504cdac80193c6440b5791b4719c08a058adb4e',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
