) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  4,
  'reduction-risk',
  'reduction-risk',
  'hemorrhage signs',
  'reduction-risk',
  'select_all',
  'A client is 1 hour after surgery. The nurse is identifying signs that need an immediate call.',
  'Which findings need an immediate call? Select all that apply.',
  '{"options":["Heart rate 130 and blood pressure 86/50","Dressing saturated with bright blood","Client asking for water","Urine output 15 mL for the hour","Client rating pain 4 out of 10"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"hemorrhage signs","kind":"select_all"}',
  'Heart rate 130 and blood pressure 86/50|||Dressing saturated with bright blood|||Urine output 15 mL for the hour',
  'The indicated choices are the ones that change the plan now. Shock vitals, a soaked dressing, and very low urine output are bleeding or perfusion problems. Incorrect: Thirst and moderate pain are expected and are not the emergency cluster.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '00ff05ce0cc56c034075f4eb51e074149a528a5f00634f0448c9cfdf2612507c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
