) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  4,
  'basic-care-comfort',
  'basic-care-comfort',
  'aspiration precautions',
  'basic-care-comfort',
  'select_all',
  'A client has dysphagia. The nurse is setting up the meal. The nurse is choosing the safest next action for this client right now.',
  'Which actions reduce aspiration? Select all that apply.',
  '{"options":["Sit the client upright","Give thin water through a straw","Stay with the client while eating","Offer nectar-thick liquids only if speech therapy ordered them","Lay the client flat immediately after two bites"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"aspiration precautions","kind":"select_all"}',
  'Sit the client upright|||Stay with the client while eating|||Offer nectar-thick liquids only if speech therapy ordered them',
  'The indicated choices are the ones that change the plan now. Upright position, supervision, and the ordered thickness reduce aspiration. Incorrect: A straw with thin liquids and lying flat push fluid toward the airway.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'a4aa6844e3d5d77715809ee1009e92f1ab478196adb1a6cc99797a22087d5540',
  'nclex-300-20261108-v1',
  'pending',
  false,
