  'nursing',
  'psychosocial',
  5,
  'psychosocial',
  'psychosocial',
  'suicide assessment',
  'psychosocial',
  'select_all',
  'A client says life is not worth living. The nurse is completing the immediate assessment. The nurse is choosing the safest next action for this client right now.',
  'Which questions are required now? Select all that apply.',
  '{"options":["Are you thinking of killing yourself?","Do you have a plan?","Do you have the means?","What is your favorite color?","Did you like breakfast?"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"suicide assessment","kind":"select_all"}',
  'Are you thinking of killing yourself?|||Do you have a plan?|||Do you have the means?',
  'The indicated choices are the ones that change the plan now. Intent, plan, and means decide how close the danger is. Incorrect: Color and breakfast preferences do not assess suicide risk.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'b161c2bcea4eeb05fa0ed78035415f67c59abf99bf278c4ee346fe7514fa5a1d',
