) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'tasks that stay with the RN',
  'management-of-care',
  'select_all',
  'The team includes an RN, an LPN, and assistive personnel. The nurse is keeping the tasks that cannot be delegated.',
  'Which tasks stay with the RN? Select all that apply.',
  '{"options":["The admission assessment","IV push lorazepam","A stable client''s bed bath","The first teaching about a new anticoagulant","Recording intake that assistive personnel already measured"],"clientNeedsCategory":"Management of Care","blueprintTopic":"tasks that stay with the RN","kind":"select_all"}',
  'The admission assessment|||IV push lorazepam|||The first teaching about a new anticoagulant',
  'The indicated choices are the ones that change the plan now. Assessment, IV push, and first teaching are RN responsibilities. Incorrect: A stable bath and recording measured intake can be delegated.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '88bd467e497dbc68e98d1a600f85e71afc92ae66bebf48cc312085f995fa7b99',
  'nclex-300-20261108-v1',
  'pending',
  false,
