) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'airborne diseases',
  'safety-infection',
  'select_all',
  'The nurse is choosing rooms for newly admitted clients. The nurse is choosing the safest next action for this client right now.',
  'Which clients need airborne precautions? Select all that apply.',
  '{"options":["Suspected measles","Pulmonary tuberculosis","Influenza","C. difficile","Varicella"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"airborne diseases","kind":"select_all"}',
  'Suspected measles|||Pulmonary tuberculosis|||Varicella',
  'The indicated choices are the ones that change the plan now. Measles, tuberculosis, and varicella spread by the airborne route. Incorrect: Influenza is droplet and C. difficile is contact. Those rooms are wrong for airborne isolation.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '6da4e1c5a13599551fa4112f6db7eef1e9aca17083b1eae7549ce9ad7624d098',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
