) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'chest tube emergencies',
  'reduction-risk',
  'select_all',
  'A client has a chest tube. The nurse is identifying findings that need immediate action. The nurse is choosing the safest next action for this client right now.',
  'Which findings need immediate action? Select all that apply.',
  '{"options":["Tracheal deviation and severe dyspnea","Continuous bubbling that is new and worsening dyspnea","A small amount of tidaling with breaths","Drainage system tipped above the chest","The client asking for a blanket"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"chest tube emergencies","kind":"select_all"}',
  'Tracheal deviation and severe dyspnea|||Continuous bubbling that is new and worsening dyspnea|||Drainage system tipped above the chest',
  'The indicated choices are the ones that change the plan now. Deviation, a new large air leak with dyspnea, and a system above the chest threaten ventilation. Incorrect: Tidaling with breaths can be normal, and a blanket request is comfort, not an emergency.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'e27bf69e0b8435299e2cd7368eca4713d3b3b6663f186b132c3e7cb1f95cb8e1',
  'nclex-300-20261108-v1',
  'pending',
  false,
