) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  4,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'high alert double checks',
  'pharmacology-nursing',
  'select_all',
  'The nurse is preparing high-alert medicines. The nurse is choosing the safest next action for this client right now.',
  'Which situations require a hold or an independent double check before the drug is given? Select all that apply.',
  '{"options":["A heparin infusion with an aPTT far above the goal","Insulin doses that do not match the order","A scheduled vitamin","A potassium infusion without a pump available","A topical moisturizer"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"high alert double checks","kind":"select_all"}',
  'A heparin infusion with an aPTT far above the goal|||Insulin doses that do not match the order|||A potassium infusion without a pump available',
  'The indicated choices are the ones that change the plan now. Heparin above goal, a mismatched insulin dose, and unpumped potassium are high-alert failures. Incorrect: A vitamin and a moisturizer are not the high-alert holds in this set.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'f3982788022bd0523d3035343345177a99d66e10e3f78981c12182ca3ac1d358',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
