  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'doffing contact precautions',
  'safety-infection',
  'ordered_response',
  'The nurse is leaving a contact-precaution room. The nurse is choosing the safest next action for this client right now.',
  'Place the removal steps in the safe order.',
  '{"options":["Remove the gown","Remove the gloves","Perform hand hygiene","Untie the gown with clean hands after gloves are off"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"doffing contact precautions","kind":"ordered_response"}',
  'Remove the gloves,Untie the gown with clean hands after gloves are off,Remove the gown,Perform hand hygiene',
  'The safe order is fixed by the risk, not by the list on the screen. Gloves come off first so the hands that touch the gown ties are not the dirty glove surface, then the gown, then hand hygiene. The display list is not the safe order. Incorrect: Removing the gown before the gloves drags contamination onto the hands.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '5a807e7ece829c3144a20f6fbdada374d1a40b756cd5f3fba3018cf425da8ce4',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
