) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'postpartum hemorrhage bow-tie',
  'reduction-risk',
  'ngn_bowtie',
  'A client who gave birth an hour ago has a boggy uterus and a pad soaked in 10 minutes. Blood pressure is 86/50.',
  'Complete the bow-tie: one action and two parameters to monitor.',
  '{"options":["Massage the fundus and call for help","Send the client to the shower","Give a full meal","Apply a cold cloth and recheck tomorrow","Amount of vaginal bleeding","Blood pressure and heart rate","Fetal heart rate","Urine glucose"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"postpartum hemorrhage bow-tie","kind":"bow_tie","condition":"Postpartum hemorrhage","actions":["Massage the fundus and call for help","Send the client to the shower","Give a full meal","Apply a cold cloth and recheck tomorrow"],"monitors":["Amount of vaginal bleeding","Blood pressure and heart rate","Fetal heart rate","Urine glucose"],"actionPickCount":1,"monitorPickCount":2}',
  'Massage the fundus and call for help,Amount of vaginal bleeding,Blood pressure and heart rate',
  'Take Massage the fundus and call for help and watch Amount of vaginal bleeding and Blood pressure and heart rate. Fundal massage and help come first. Bleeding and vital signs show whether shock is worsening. Incorrect: A shower, a meal, waiting until tomorrow, a fetal heart rate after birth, and urine glucose do not stop hemorrhage.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '7e116131306631d44143504292ab5290e996aa591c6dbab1c0812994602be523',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  5,
  'safety-infection',
  'safety-infection',
  'anaphylaxis bow-tie',
  'safety-infection',
  'ngn_bowtie',
  'A client receiving IV iron develops wheezing, hives, and a blood pressure of 78/46. The nurse is choosing the safest next action for this client right now.',
  'Complete the bow-tie: one action and two parameters to monitor.',
  '{"options":["Stop the infusion and give intramuscular epinephrine","Speed the infusion","Give oral diphenhydramine only","Finish the bag","Airway sounds","Blood pressure","Daily weight","Stool color"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"anaphylaxis bow-tie","kind":"bow_tie","condition":"Anaphylaxis during an infusion","actions":["Stop the infusion and give intramuscular epinephrine","Speed the infusion","Give oral diphenhydramine only","Finish the bag"],"monitors":["Airway sounds","Blood pressure","Daily weight","Stool color"],"actionPickCount":1,"monitorPickCount":2}',
  'Stop the infusion and give intramuscular epinephrine,Airway sounds,Blood pressure',
  'Take Stop the infusion and give intramuscular epinephrine and watch Airway sounds and Blood pressure. The drug stops and epinephrine is given. Airway and blood pressure show if shock is reversing. Incorrect: Speeding or finishing the bag, an oral antihistamine alone, weight, and stool color leave anaphylaxis in place.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '735bab6f462e2ad17c0bedf55db9230dee5e45d454290f55e6340b3a8c54170d',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'health-promotion',
  4,
  'health-promotion',
  'health-promotion',
  'vaccine timing matrix',
  'health-promotion',
  'ngn_matrix',
  'A nurse is matching vaccines to clients at a clinic. Each client is here for a scheduled visit and none has a fever today.',
  'For each client, select whether the vaccine is given today.',
  '{"options":["Healthy newborn before discharge|||Give the indicated vaccine","Healthy newborn before discharge|||Do not give today","12-month-old due for measles vaccine|||Give the indicated vaccine","12-month-old due for measles vaccine|||Do not give today","Pregnant client asking about live measles vaccine today|||Give the indicated vaccine","Pregnant client asking about live measles vaccine today|||Do not give today","65-year-old who has never had a pneumonia vaccine|||Give the indicated vaccine","65-year-old who has never had a pneumonia vaccine|||Do not give today"],"clientNeedsCategory":"Health Promotion and Maintenance","blueprintTopic":"vaccine timing matrix","kind":"matrix","rows":["Healthy newborn before discharge","12-month-old due for measles vaccine","Pregnant client asking about live measles vaccine today","65-year-old who has never had a pneumonia vaccine"],"columns":["Give the indicated vaccine","Do not give today"],"rowHeader":"Finding"}',
  'Healthy newborn before discharge|||Give the indicated vaccine,12-month-old due for measles vaccine|||Give the indicated vaccine,Pregnant client asking about live measles vaccine today|||Do not give today,65-year-old who has never had a pneumonia vaccine|||Give the indicated vaccine',
  'Each finding is classified by the action it requires. Hepatitis B at birth, measles at 12 months, and pneumonia vaccine for the older adult match the schedule. Live measles vaccine is not given in pregnancy. Incorrect: Giving the live vaccine in pregnancy or skipping the newborn and older-adult doses is the error.',
  '["nclex","NCLEX-RN-2026","health-promotion","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Adult immunization schedule. CDC 2026","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/adult-notes.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
