) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'contact organisms',
  'safety-infection',
  'select_all',
  'The charge nurse is placing newly admitted clients. The nurse is choosing the safest next action for this client right now.',
  'Which clients need contact precautions? Select all that apply.',
  '{"options":["C. difficile diarrhea","Draining MRSA wound","Influenza only","Closed fracture","Scabies"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"contact organisms","kind":"select_all"}',
  'C. difficile diarrhea|||Draining MRSA wound|||Scabies',
  'The indicated choices are the ones that change the plan now. C. difficile, draining MRSA, and scabies spread by contact. Incorrect: Influenza is droplet and a closed fracture needs standard precautions.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'cdcc77fc49fdee859a2bd1a24b0622e2a84cdd23815c532362bad40adb0d78f3',
  'nclex-300-20261108-v1',
  'pending',
  false,
