  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'RN-only work',
  'management-of-care',
  'select_all',
  'The team is dividing the assignment. The nurse is choosing the safest next action for this client right now.',
  'Which tasks must the RN keep? Select all that apply.',
  '{"options":["New admission assessment","IV push opioid","Stable linen change","First teaching on warfarin","Recording a measured urine output"],"clientNeedsCategory":"Management of Care","blueprintTopic":"RN-only work","kind":"select_all"}',
  'New admission assessment|||IV push opioid|||First teaching on warfarin',
  'The indicated choices are the ones that change the plan now. Assessment, IV push, and first teaching stay with the RN. Incorrect: Linen and recording a measured output can be delegated on a stable client.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
