) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'shock findings',
  'reduction-risk',
  'select_all',
  'A postoperative client is being assessed. The nurse is choosing the safest next action for this client right now.',
  'Which findings suggest shock and need immediate action? Select all that apply.',
  '{"options":["Blood pressure 80/46","Heart rate 132","Warm request for a blanket only","Urine output 10 mL in an hour","Pain score of 3"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"shock findings","kind":"select_all"}',
  'Blood pressure 80/46|||Heart rate 132|||Urine output 10 mL in an hour',
  'The indicated choices are the ones that change the plan now. Hypotension, tachycardia, and very low urine output are shock. Incorrect: A blanket request and mild pain are not the shock cluster.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'a50b0f39a3695ee505c1ffffd5f938671789994b497573ae30ae258b6c51db35',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
