) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  4,
  'basic-care-comfort',
  'basic-care-comfort',
  'aspiration bow-tie',
  'basic-care-comfort',
  'ngn_bowtie',
  'A client with a stroke coughs, has a wet voice after a sip of water, and the oxygen saturation falls from 97 to 90 percent.',
  'Complete the bow-tie: one action and two parameters to monitor.',
  '{"options":["Stop oral intake and sit the client up","Give more water to clear the throat","Lay the client flat","Start a regular diet","Oxygen saturation","Respiratory rate","Weekly weight","Hair growth"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"aspiration bow-tie","kind":"bow_tie","condition":"Suspected aspiration","actions":["Stop oral intake and sit the client up","Give more water to clear the throat","Lay the client flat","Start a regular diet"],"monitors":["Oxygen saturation","Respiratory rate","Weekly weight","Hair growth"],"actionPickCount":1,"monitorPickCount":2}',
  'Stop oral intake and sit the client up,Oxygen saturation,Respiratory rate',
  'Take Stop oral intake and sit the client up and watch Oxygen saturation and Respiratory rate. Coughing and a falling saturation mean oral intake stops and the airway is supported. Incorrect: More water, lying flat, a regular diet, weight, and hair growth worsen aspiration.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '33efddab19e15d83366fc86a0f1b6251aee4987990f260263af3bdd41a701c7a',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
