  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  5,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'opioid depression bow-tie',
  'pharmacology-nursing',
  'ngn_bowtie',
  'A client received morphine 15 minutes ago. The respiratory rate is 6 and the client does not wake to voice.',
  'Complete the bow-tie: one action and two parameters to monitor.',
  '{"options":["Support breathing and give naloxone as ordered","Give another dose of morphine","Start a benzodiazepine","Offer oral fluids","Respiratory rate","Level of consciousness","Daily weight","Stool frequency"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"opioid depression bow-tie","kind":"bow_tie","condition":"Opioid-induced respiratory depression","actions":["Support breathing and give naloxone as ordered","Give another dose of morphine","Start a benzodiazepine","Offer oral fluids"],"monitors":["Respiratory rate","Level of consciousness","Daily weight","Stool frequency"],"actionPickCount":1,"monitorPickCount":2}',
  'Support breathing and give naloxone as ordered,Respiratory rate,Level of consciousness',
  'Take Support breathing and give naloxone as ordered and watch Respiratory rate and Level of consciousness. A rate of 6 and unresponsiveness after morphine is reversed with naloxone while breathing is supported. Incorrect: More morphine, a benzodiazepine, fluids, weight, and stool frequency deepen or ignore the depression.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '50ba766145e0addc26a99103380f00e9590232c0f4ce28fca7e077916fbc98e9',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
