) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  4,
  'reduction-risk',
  'reduction-risk',
  'adult choking',
  'reduction-risk',
  'ordered_response',
  'An adult client is clutching the throat and cannot cough or speak. The nurse is choosing the safest next action for this client right now.',
  'Place the actions in the safe order.',
  '{"options":["Give abdominal thrusts","Confirm the client cannot speak or cough","Call for help if the client becomes unresponsive","Start CPR if the client becomes unresponsive"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"adult choking","kind":"ordered_response"}',
  'Confirm the client cannot speak or cough,Give abdominal thrusts,Call for help if the client becomes unresponsive,Start CPR if the client becomes unresponsive',
  'The safe order is fixed by the risk, not by the list on the screen. Severe obstruction is confirmed, thrusts are given, and CPR starts only if the client becomes unresponsive. The screen list is not that order. Incorrect: Starting with thrusts before confirming, or CPR while the client is still standing, is the wrong sequence.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'ab30a38dfd825e05ea34e615dea053fb95868953c008ddb81be474397cdaab92',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
