  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'precaution matrix two',
  'safety-infection',
  'ngn_matrix',
  'Four clients arrive at the same time. None is immunocompromised. The nurse is choosing the safest next action for this client right now.',
  'For each client, select the transmission precaution.',
  '{"options":["Measles|||Airborne","Measles|||Droplet","Measles|||Contact","Measles|||Standard","Influenza|||Airborne","Influenza|||Droplet","Influenza|||Contact","Influenza|||Standard","C. difficile|||Airborne","C. difficile|||Droplet","C. difficile|||Contact","C. difficile|||Standard","Closed ankle fracture|||Airborne","Closed ankle fracture|||Droplet","Closed ankle fracture|||Contact","Closed ankle fracture|||Standard"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"precaution matrix two","kind":"matrix","rows":["Measles","Influenza","C. difficile","Closed ankle fracture"],"columns":["Airborne","Droplet","Contact","Standard"],"rowHeader":"Finding"}',
  'Measles|||Airborne,Influenza|||Droplet,C. difficile|||Contact,Closed ankle fracture|||Standard',
  'Each finding is classified by the action it requires. Measles is airborne, influenza is droplet, C. difficile is contact, and a closed fracture uses standard precautions. Incorrect: Swapping those routes isolates the wrong client or exposes roommates.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '6945a8ff2aae8778b06c5bac857e71f6b275617130121bcc82c7d4c75faf04a7',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
