) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  4,
  'basic-care-comfort',
  'basic-care-comfort',
  'pressure relief choices',
  'basic-care-comfort',
  'select_all',
  'A client has a sacral pressure injury and is in bed. The nurse is choosing the safest next action for this client right now.',
  'Which actions protect the skin? Select all that apply.',
  '{"options":["Turn at least every 2 hours","Float the heels","Massage the reddened sacrum","Keep the skin dry after incontinence","Leave the client on a bedpan for hours"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"pressure relief choices","kind":"select_all"}',
  'Turn at least every 2 hours|||Float the heels|||Keep the skin dry after incontinence',
  'The indicated choices are the ones that change the plan now. Turning, offloading heels, and dry skin reduce pressure injury. Incorrect: Massage of reddened skin and a long time on a bedpan worsen breakdown.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '68e0385a274d6f84f5efd99b423617ac3787894a74124532e927321f76ceb23e',
  'nclex-300-20261108-v1',
  'pending',
