) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'fall prevention bundle',
  'safety-infection',
  'select_all',
  'An older client received an opioid and needs to toilet. The nurse is choosing the safest next action for this client right now.',
  'Which actions belong in the fall plan? Select all that apply.',
  '{"options":["Stay with the client during the toilet","Leave the bed in the high position","Keep the call light in reach","Put nonskid footwear on","Turn off the bed alarm to reduce noise"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"fall prevention bundle","kind":"select_all"}',
  'Stay with the client during the toilet|||Keep the call light in reach|||Put nonskid footwear on',
  'The indicated choices are the ones that change the plan now. A recently medicated client is not left alone to toilet. The call light and footwear help. Incorrect: A high bed and a disabled alarm increase the chance of a fall.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'a215426bb810f8e1c44c022f9da7ac23ecdbc61cd2da75b21b69e3a549d4be62',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
