) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'handoff essentials',
  'management-of-care',
  'select_all',
  'A client is being transferred to another unit. The nurse is choosing the safest next action for this client right now.',
  'Which facts must be included in the handoff? Select all that apply.',
  '{"options":["Allergies","Code status","The nurse''s lunch order","Current vital-sign concerns","Favorite television channel"],"clientNeedsCategory":"Management of Care","blueprintTopic":"handoff essentials","kind":"select_all"}',
  'Allergies|||Code status|||Current vital-sign concerns',
  'The indicated choices are the ones that change the plan now. Allergies, code status, and unstable vitals change the receiving nurse''s first actions. Incorrect: Lunch and television are not safety handoff content.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'cc0a4b133abfee07f5d601414e4291004886ff6a51c2440b48c893bf903b81b0',
