) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'psychosocial',
  5,
  'psychosocial',
  'psychosocial',
  'means restriction',
  'psychosocial',
  'select_all',
  'A client with suicidal intent is admitted from home. The nurse is choosing the safest next action for this client right now.',
  'Which actions reduce access to means? Select all that apply.',
  '{"options":["Remove belts and shoelaces","Search belongings with a witness","Leave a private locked bathroom","Keep one-to-one observation","Allow the client to keep a pocket knife for comfort"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"means restriction","kind":"select_all"}',
  'Remove belts and shoelaces|||Search belongings with a witness|||Keep one-to-one observation',
  'The indicated choices are the ones that change the plan now. Means are removed and the client is observed. A search is done with respect and a witness. Incorrect: A locked bathroom and a pocket knife keep lethal access.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '005bf3d1de2e90c7dd9eca3d508ca1a5650cd2c6922ee3ef51024816c7749a5b',
  'nclex-300-20261108-v1',
  'pending',
  false,
