  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  4,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'insulin safety',
  'pharmacology-nursing',
  'select_all',
  'The nurse is about to give insulin. The nurse is choosing the safest next action for this client right now.',
  'Which checks are required? Select all that apply.',
  '{"options":["Match the dose to the order and the glucose","Use a second nurse when the policy requires an independent check","Give it without reading the label if the vial color looks right","Know the client''s meal status","Borrow another client''s insulin pen"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"insulin safety","kind":"select_all"}',
  'Match the dose to the order and the glucose|||Use a second nurse when the policy requires an independent check|||Know the client''s meal status',
  'The indicated choices are the ones that change the plan now. Dose, glucose, meal status, and a policy double-check prevent insulin errors. Incorrect: Skipping the label or borrowing a pen is a medication error.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '6ab501da39a9cf385b570092067df1436aef667166e1b3a2acf2d5c5b3a4e220',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
