  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'delegation to assistive personnel',
  'management-of-care',
  'vignette',
  'Four clients are assigned at 0730. One unlicensed assistive person is available. A client who had a stroke yesterday needs a bed bath and has a stable Glasgow score of 15. A second client needs a first postoperative dressing change. A third needs a new IV catheter. A fourth needs intake and output recorded.',
  'Which task is appropriate to delegate to the assistive personnel?',
  '{"options":["The first dressing change","Starting the IV catheter","Recording intake and output","Teaching the stroke client about aspiration"],"clientNeedsCategory":"Management of Care","blueprintTopic":"delegation to assistive personnel","kind":"mcq"}',
  'Recording intake and output',
  'Recording intake and output is the nurse''s action. Intake and output is a stable measurement task within assistive-personnel scope when the nurse has assessed the client. Incorrect: A first dressing change, IV insertion, and initial teaching are nursing assessments or invasive skills and stay with the nurse.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'f499d4ffa3bcd9a5e0c366e405bf4da362fcff0ea9fe1ecd9f476aefd6dae937',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'who to see first',
  'management-of-care',
  'vignette',
  'The nurse has just received report on four clients. One is 2 hours after a thyroidectomy and now has a harsh high-pitched sound on inspiration. One asks for a PRN stool softener. One has a blood glucose of 168 mg/dL before lunch and a sliding-scale order. One wants the discharge papers explained again.',
  'Which client does the nurse see first?',
  '{"options":["The client asking for a stool softener","The client with a glucose of 168 mg/dL","The client who wants discharge teaching repeated","The client with the harsh inspiratory sound"],"clientNeedsCategory":"Management of Care","blueprintTopic":"who to see first","kind":"mcq"}',
  'The client with the harsh inspiratory sound',
  'The client with the harsh inspiratory sound is the nurse''s action. Stridor after thyroidectomy is airway obstruction until the nurse is at the bedside. Airway comes before routine medications and teaching. Incorrect: A stool softener, a glucose of 168, and repeat teaching are not immediate airway threats.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '7ab07ba349f2112f6e2e48896957e1dd171ab7eca548a93bae86b95ad005f681',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'informed consent witness',
  'management-of-care',
  'vignette',
  'A client is scheduled for a cardiac catheterization. The cardiologist has not yet discussed risks. The client asks the nurse to explain the chance of stroke and then sign the consent so the procedure is not delayed.',
  'Which action does the nurse take?',
  '{"options":["Explain the stroke risk and sign as the witness","Ask the cardiologist to return and complete the discussion before the nurse witnesses the signature","Have the client sign and write that teaching was deferred","Tell the client the risk is too small to review"],"clientNeedsCategory":"Management of Care","blueprintTopic":"informed consent witness","kind":"mcq"}',
  'Ask the cardiologist to return and complete the discussion before the nurse witnesses the signature',
  'Ask the cardiologist to return and complete the discussion before the nurse witnesses the signature is the nurse''s action. The nurse may witness a signature and confirm that the client was informed. The nurse does not replace the practitioner who is responsible for explaining procedure-specific risks. Incorrect: Signing before that discussion, minimizing the risk, or documenting that teaching was skipped leaves the consent incomplete.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'd40c3bdbc6c1f98efe7c79ff8a51e00b866917ccc8833c2cd3ed010c174256d0',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'advance directive versus family',
  'management-of-care',
  'vignette',
  'A client with decision-making capacity has a signed advance directive refusing intubation. The client is now tiring from pneumonia and still refuses a tube. An adult child at the bedside demands that the team intubate.',
  'Which action is correct?',
  '{"options":["Intubate because the child is the next of kin","Follow the client''s refusal and the advance directive","Ask the child to sign a new consent that overrides the directive","Sedate the client and intubate while the refusal is being discussed"],"clientNeedsCategory":"Management of Care","blueprintTopic":"advance directive versus family","kind":"mcq"}',
  'Follow the client''s refusal and the advance directive',
  'Follow the client''s refusal and the advance directive is the nurse''s action. A capacitated client''s current refusal controls. An advance directive supports that refusal. Family disagreement does not replace it. Incorrect: Intubation over a current refusal, a child''s signature, or sedation to bypass the refusal are not authorized.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '4dabf1e96653b3ba8b7a58e99798619834c2e1067de8ee2938dbff4f48481f7b',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
