  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'confidentiality and a caller',
  'management-of-care',
  'vignette',
  'A person who says they are the client''s spouse calls the nurses'' station and asks for the results of today''s biopsy. The client has not authorized any disclosure. The spouse is not listed on the release.',
  'Which response is appropriate?',
  '{"options":["Read the biopsy result because spouses are automatically entitled to it","Say that information cannot be released without the client''s permission","Leave the result on the spouse''s voicemail","Confirm the diagnosis but not the stage"],"clientNeedsCategory":"Management of Care","blueprintTopic":"confidentiality and a caller","kind":"mcq"}',
  'Say that information cannot be released without the client''s permission',
  'Say that information cannot be released without the client''s permission is the nurse''s action. Diagnosis and test results are protected. Relationship alone is not authorization. Incorrect: Reading the result, leaving a voicemail, or confirming the diagnosis still discloses protected information.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '448bfe237cf45cd09bd5cef20c34499c4336ef2a1b2b84da4a526303afee3698',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'refusal with capacity',
  'management-of-care',
  'vignette',
  'A client with capacity understands that leaving before antibiotics for pyelonephritis risks sepsis. The client can repeat that risk and still wants to go home. The client is not suicidal.',
  'Which action is appropriate?',
  '{"options":["Restrain the client until the next antibiotic dose","Document the discussion, offer prescriptions and return instructions, and let the client leave","Tell the client that leaving cancels all future care","Give the antibiotic by force and then discharge"],"clientNeedsCategory":"Management of Care","blueprintTopic":"refusal with capacity","kind":"mcq"}',
  'Document the discussion, offer prescriptions and return instructions, and let the client leave',
  'Document the discussion, offer prescriptions and return instructions, and let the client leave is the nurse''s action. A capacitated refusal is honored after the risk is understood. The nurse documents and keeps a safe way back. Incorrect: Restraints, a ban on future care, and forced medication are not the response to a capacitated refusal.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'c8806fd9a637b8fc569deec771d01e0ed8b09ecc55645da598a6e3d04549cf85',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'disaster triage',
  'management-of-care',
  'vignette',
  'A nurse is the first clinician at a bus crash and is using simple triage. One victim is not breathing after the airway is opened and has no pulse. One victim cannot walk, has a respiratory rate of 34, and has delayed capillary refill. One victim is walking with a broken wrist. One victim had bleeding that stopped with a pressure dressing and is now walking.',
  'Which victim is tagged immediate, or red?',
  '{"options":["The victim who is not breathing after the airway is opened and has no pulse","The walking victim with a broken wrist","The victim who cannot walk, with a respiratory rate of 34 and delayed capillary refill","The victim who is walking after the bleeding stopped"],"clientNeedsCategory":"Management of Care","blueprintTopic":"disaster triage","kind":"mcq"}',
  'The victim who cannot walk, with a respiratory rate of 34 and delayed capillary refill',
  'In simple triage, a victim who cannot walk, breathes faster than 30, or has delayed capillary refill is immediate. A victim who does not breathe after the airway is opened is expectant when many people are hurt. Walking victims are minimal. Incorrect: treating the expectant or the walking victims first delays the person who can still be saved now.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '95713846ef805c729c852639fcb1960d58ba8d12127c422f6284935c4d08019d',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'handoff missing a critical fact',
  'management-of-care',
  'vignette',
  'A nurse receives a telephone handoff that omits the client''s allergy and code status. The sending nurse is about to hang up because the ambulance is leaving.',
  'Which statement is the best response?',
  '{"options":["Accept the report and look up the allergy later if there is time","Ask the sending nurse to state allergies and code status before the call ends","Document that the handoff was complete","Ask the ambulance driver to recall the code status"],"clientNeedsCategory":"Management of Care","blueprintTopic":"handoff missing a critical fact","kind":"mcq"}',
  'Ask the sending nurse to state allergies and code status before the call ends',
  'Ask the sending nurse to state allergies and code status before the call ends is the nurse''s action. A handoff is not complete until critical safety facts are exchanged. The receiving nurse closes that gap before the source of the information is gone. Incorrect: Deferring the allergy, calling the report complete, or asking the driver substitutes an unreliable source.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'f6cb6a948cdde7ba5ce62c1664b45a4dd148e585135c6ab3346aec25019b25c9',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'floating nurse assignment',
  'management-of-care',
  'vignette',
  'A medical-surgical nurse is floated to the postpartum unit for one shift and has not had obstetric orientation. The charge nurse is making assignments.',
  'Which assignment is safest?',
  '{"options":["A client who is being admitted in active labor","A stable 1-day postpartum client who needs routine assessments and discharge teaching the obstetric nurse has already started","A client with magnesium sulfate for severe preeclampsia","A client recovering from an emergency cesarean with a draining incision"],"clientNeedsCategory":"Management of Care","blueprintTopic":"floating nurse assignment","kind":"mcq"}',
  'A stable 1-day postpartum client who needs routine assessments and discharge teaching the obstetric nurse has already started',
  'A stable 1-day postpartum client who needs routine assessments and discharge teaching the obstetric nurse has already started is the nurse''s action. A floated nurse should receive stable clients whose needs match medical-surgical skills. Unstable obstetric complications and active labor stay with obstetric nurses. Incorrect: Labor, magnesium sulfate, and a fresh complicated postoperative course require specialty judgment the float nurse has not been oriented to perform.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'f483a08d8340924d36d7da839b426ac83ebc0712c4b1a4918f21d080354b9a19',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'incident report versus the chart',
  'management-of-care',
  'vignette',
  'A nurse gives 4 units of insulin instead of 2 units. The client''s glucose is rechecked and treated, and the client recovers. The nurse is documenting.',
  'Which documentation is appropriate?',
  '{"options":["Write the error only in the incident report and leave the medical record blank","Record the dose given, the glucose, and the treatment in the medical record, and complete a separate incident report","Alter the medication administration record to show 2 units","Chart that the client requested the extra dose"],"clientNeedsCategory":"Management of Care","blueprintTopic":"incident report versus the chart","kind":"mcq"}',
  'Record the dose given, the glucose, and the treatment in the medical record, and complete a separate incident report',
  'Record the dose given, the glucose, and the treatment in the medical record, and complete a separate incident report is the nurse''s action. The record states facts of care. The incident report is the quality tool and is not a substitute for the record, and the record is not altered. Incorrect: Leaving the record blank, changing the dose, or inventing a client request falsifies or hides the event.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'ba7adb071a9f220caa7b5eb3c32f9b7d8a3fbfe0191a582d38713ac060cabf29',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'LPN scope',
  'management-of-care',
  'vignette',
  'A stable client needs a wound irrigation that the LPN has performed before, a new admission assessment, and discharge teaching that has not been started. An RN and an LPN are on the team.',
  'Which task may the RN assign to the LPN?',
  '{"options":["The new admission assessment","The first discharge teaching","The familiar wound irrigation on the stable client","The care plan for a client whose condition just changed"],"clientNeedsCategory":"Management of Care","blueprintTopic":"LPN scope","kind":"mcq"}',
  'The familiar wound irrigation on the stable client',
  'The familiar wound irrigation on the stable client is the nurse''s action. An LPN may perform a known procedure on a stable client. New assessments, first teaching, and an unstable plan stay with the RN. Incorrect: Assigning the admission, the first teaching, or the changing client gives the LPN work that requires the RN''s assessment.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'f78a9f28648eff0073930a11bfdb42bcb033a81a1aaa311d7f9f48d9153d05ac',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'UAP and a new symptom',
  'management-of-care',
  'vignette',
  'Assistive personnel report that a client who was walking an hour ago now says the chest feels tight. The nurse is in another room passing medications that are not time-critical.',
  'What is the nurse''s best direction?',
  '{"options":["Finish the medication pass, then assess the chest tightness","Ask the assistive person to take vital signs and report back in 30 minutes","Stop and assess the client with chest tightness now","Tell the assistive person to have the client take a nitroglycerin tablet"],"clientNeedsCategory":"Management of Care","blueprintTopic":"UAP and a new symptom","kind":"mcq"}',
  'Stop and assess the client with chest tightness now',
  'Stop and assess the client with chest tightness now is the nurse''s action. A new report of chest tightness is a nurse assessment, not a task to postpone or delegate. Incorrect: Finishing the pass, delaying vital signs, or having assistive personnel give nitroglycerin skips or misplaces the assessment.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '2bd368e4d1a21033992ec456b4c18a0f4d1e8b3e81dab988aa3b8f9f47430973',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'ethical advocacy',
  'management-of-care',
  'vignette',
  'A client does not understand tomorrow''s surgery. The surgeon is still in the hospital. The client asks the nurse to advocate so the decision is not made in confusion.',
  'Which action advocates for the client?',
  '{"options":["Tell the client to sign so the operating room schedule is kept","Call the surgeon to return and speak with the client before consent","Ask a roommate to explain the surgery","Document that the client seemed nervous and send the client anyway"],"clientNeedsCategory":"Management of Care","blueprintTopic":"ethical advocacy","kind":"mcq"}',
  'Call the surgeon to return and speak with the client before consent',
  'Call the surgeon to return and speak with the client before consent is the nurse''s action. Advocacy here is arranging the person who can explain the procedure before consent. Incorrect: Keeping the schedule, using a roommate, or sending a confused client does not protect an informed decision.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
