  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'mandatory reporting',
  'management-of-care',
  'vignette',
  'An older client has bruises in different stages on both upper arms and says a caregiver grabs them during arguments. The client asks the nurse not to tell anyone.',
  'What does the nurse do?',
  '{"options":["Promise secrecy because the client requested it","Report the suspected abuse as required and tell the client what must be reported","Wait until the client agrees in writing","Document the bruises and discharge the client with the caregiver"],"clientNeedsCategory":"Management of Care","blueprintTopic":"mandatory reporting","kind":"mcq"}',
  'Report the suspected abuse as required and tell the client what must be reported',
  'Report the suspected abuse as required and tell the client what must be reported is the nurse''s action. Suspected abuse of a vulnerable adult is reported. The nurse does not promise a secrecy that the law does not allow. Incorrect: Secrecy, waiting for written consent, or sending the client home with the caregiver leaves the risk unreported.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '27a3c6061805a84ab1d4bd57443e714aaab9206fe73377255c5c52d0508a98d0',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'priority after report',
  'management-of-care',
  'vignette',
  'Report includes a client with a potassium of 6.4 mEq/L and peaked T waves, a client who needs a routine colostomy bag change, a client requesting a sleeping pill at 2100, and a client whose family wants an update.',
  'Whom does the nurse see first?',
  '{"options":["The client who wants a sleeping pill","The client with potassium 6.4 mEq/L and peaked T waves","The family waiting for an update","The client needing a colostomy bag change"],"clientNeedsCategory":"Management of Care","blueprintTopic":"priority after report","kind":"mcq"}',
  'The client with potassium 6.4 mEq/L and peaked T waves',
  'The client with potassium 6.4 mEq/L and peaked T waves is the nurse''s action. Peaked T waves with severe hyperkalemia can progress to a lethal rhythm and come before routine care and updates. Incorrect: A sleeping pill, a family update, and a bag change are not the immediate threat.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'fca2c498b3bf6ccf5cb5b6862a63b5f3574b9a36ceaa8a869559c2407d5a0d0c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
