  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'assignment of an unstable client',
  'management-of-care',
  'vignette',
  'A new graduate RN, an experienced RN, an LPN, and assistive personnel are on duty. One client was just started on a heparin infusion for a pulmonary embolism and has new shortness of breath.',
  'Who should receive that client?',
  '{"options":["The assistive personnel","The LPN","The experienced RN","The new graduate working alone without a preceptor at the bedside"],"clientNeedsCategory":"Management of Care","blueprintTopic":"assignment of an unstable client","kind":"mcq"}',
  'The experienced RN',
  'The experienced RN is the nurse''s action. A client with a new heparin infusion and worsening breathing needs the experienced RN''s judgment. Incorrect: Assistive personnel and the LPN cannot manage this instability, and an unsupervised new graduate should not carry it alone.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '4f5b926c2edcc9d624265968a6daa8c7304671afb08c1424bcef9dd1577a0e3f',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
