  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'translator for consent',
  'management-of-care',
  'vignette',
  'A client who speaks little English is asked to sign a consent. The adult child offers to interpret the surgeon''s risk discussion. A video interpreter is available in two minutes.',
  'Which interpreter does the nurse arrange?',
  '{"options":["The adult child, to save time","The qualified video interpreter","A bilingual housekeeper passing in the hall","No interpreter, using gestures"],"clientNeedsCategory":"Management of Care","blueprintTopic":"translator for consent","kind":"mcq"}',
  'The qualified video interpreter',
  'The qualified video interpreter is the nurse''s action. Procedure consent needs a qualified interpreter. A child or an untrained staff member is not that role. Incorrect: Using the child, a passerby, or gestures risks an inaccurate consent.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '6efa4d7daf72553024f42c30d6c1a237cc2ffe82e1752774f412b27b7985e3e2',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
