  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'DNR and surgery',
  'management-of-care',
  'vignette',
  'A capacitated client with a do-not-resuscitate order is going to the operating room for a palliative procedure. The anesthesiologist has not discussed the order.',
  'What does the nurse support?',
  '{"options":["Automatically suspend the order without talking to the client","Review the order with the client and the perioperative team and document the agreed plan","Cancel the order because surgery is resuscitation","Ask the family to decide because the client is going to sleep"],"clientNeedsCategory":"Management of Care","blueprintTopic":"DNR and surgery","kind":"mcq"}',
  'Review the order with the client and the perioperative team and document the agreed plan',
  'Review the order with the client and the perioperative team and document the agreed plan is the nurse''s action. Perioperative code status is reconsidered with the client, not silently suspended or cancelled. Incorrect: Automatic suspension, treating surgery as a cancelled order, or handing the choice to the family skips the client''s decision.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'c21a8844ff27a36ddc8bf8a07ab8677e444382f51160619daaba46f16d061208',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
