) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'resource triage on the unit',
  'management-of-care',
  'vignette',
  'Two clients call at once. One has a new facial droop and arm weakness that started 20 minutes ago. The other needs help to the bathroom and has been waiting 10 minutes.',
  'Whom does the nurse see first?',
  '{"options":["The client who needs the bathroom","The client with the new facial droop and arm weakness","Whichever client called first","The client closest to the nurses'' station if that is the bathroom call"],"clientNeedsCategory":"Management of Care","blueprintTopic":"resource triage on the unit","kind":"mcq"}',
  'The client with the new facial droop and arm weakness',
  'The client with the new facial droop and arm weakness is the nurse''s action. Sudden focal deficits are a stroke emergency. Toileting can be covered by another team member. Incorrect: Order of the call or proximity does not outrank a possible stroke.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '697288f81cd296eab1cc060c3752dad749c5d8ac5fd5cdb2bf601ed09d00e03e',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
