) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  3,
  'management-of-care',
  'management-of-care',
  'social media',
  'management-of-care',
  'vignette',
  'A nurse wants to post a de-identified story about a rare diagnosis from today''s shift, including the hospital unit and the day.',
  'Which action is appropriate?',
  '{"options":["Post it because the name was removed","Do not post client information from the shift","Post it to a private staff group","Post the photo of the monitor with the name cropped"],"clientNeedsCategory":"Management of Care","blueprintTopic":"social media","kind":"mcq"}',
  'Do not post client information from the shift',
  'Do not post client information from the shift is the nurse''s action. Unit, date, and a rare story can identify a client. Removing the name is not enough. Incorrect: A private group or a cropped monitor photo can still be a disclosure.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '9fee2a9178f744cf762430af2ee656c86875f2786b59c0cadc1b6e2c4010c042',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
