) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  5,
  'safety-infection',
  'safety-infection',
  'airborne precautions',
  'safety-infection',
  'vignette',
  'A client has fever, cough, and a rash that started on the face. Measles is suspected. The client is in a shared semi-private room.',
  'Which placement does the nurse arrange?',
  '{"options":["A shared room with a surgical mask on the client only","A private airborne-infection isolation room and a respirator for staff entering","Contact precautions in the current room","Droplet precautions with the door open"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"airborne precautions","kind":"mcq"}',
  'A private airborne-infection isolation room and a respirator for staff entering',
  'A private airborne-infection isolation room and a respirator for staff entering is the nurse''s action. Measles is airborne. The client needs airborne isolation and staff need a respirator, not a surgical mask alone. Incorrect: A shared room, contact precautions, or an open door do not contain airborne virus.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'e3d626c6bfb28911f30cbf456f9fb83cda30850fd73d42083d7180b1b5e9b7bc',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'droplet precautions',
  'safety-infection',
  'vignette',
  'A client is admitted with suspected meningococcal meningitis. The client is maskless in the hallway returning from imaging.',
  'What does the nurse do first?',
  '{"options":["Place a surgical mask on the client and complete droplet precautions","Start airborne isolation with an N95 only","Remove precautions because the hallway trip is over","Use gloves only"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"droplet precautions","kind":"mcq"}',
  'Place a surgical mask on the client and complete droplet precautions',
  'Place a surgical mask on the client and complete droplet precautions is the nurse''s action. Meningococcus spreads by droplets. A surgical mask and droplet precautions are the immediate control. Incorrect: Airborne isolation, ending precautions, or gloves alone miss droplet spread.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'ae404c78945570aa14d4ffc92e93295f783c72f9494c0107a400ad79ba314f17',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'contact precautions',
  'safety-infection',
  'vignette',
  'A client has watery stool and a positive Clostridioides difficile test. The roommate has no symptoms.',
  'Which practice does the nurse use?',
  '{"options":["Alcohol hand rub alone after glove removal","Soap and water after glove removal, plus contact precautions","A surgical mask as the only addition","Standard precautions without a gown"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"contact precautions","kind":"mcq"}',
  'Soap and water after glove removal, plus contact precautions',
  'Soap and water after glove removal, plus contact precautions is the nurse''s action. C. difficile spores are not killed by alcohol gel. Soap and water and contact precautions are required. Incorrect: Alcohol gel alone, a mask only, or no gown leave spores on hands and surfaces.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '2abbea894504f6842eed4ddfc94ceb1b7503cf6f7c12460b2bcaf1c6b2504f97',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'fall risk highest',
  'safety-infection',
  'vignette',
  'Four clients are on the unit. One is older, received a new opioid an hour ago, and has an urgent need to toilet. One is young and waiting for discharge teaching. One is sleeping after a physical therapy session with the bed alarm on. One is alert and using a walker independently.',
  'Which client does the nurse help first to prevent a fall?',
  '{"options":["The client waiting for discharge teaching","The older client who received an opioid and needs to toilet","The sleeping client with the bed alarm on","The client using a walker independently"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"fall risk highest","kind":"mcq"}',
  'The older client who received an opioid and needs to toilet',
  'The older client who received an opioid and needs to toilet is the nurse''s action. New opioid sedation plus an urgent toilet need is the highest fall risk right now. Incorrect: Teaching, a sleeping client already alarmed, and independent walker use are lower immediate risks.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '829980340b13b32c59e61e9781647a6b210564450d320b48806b388377a0ef4e',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  5,
  'safety-infection',
  'safety-infection',
  'restraints',
  'safety-infection',
  'vignette',
  'A client is pulling at a nasogastric tube. The nurse has not yet tried reorientation, a sitter, or camouflage of the tube. A coworker suggests bilateral wrist restraints.',
  'Which action comes first?',
  '{"options":["Apply restraints so the tube stays in","Try less restrictive measures and have the nurse stay with the client","Tie the wrists to the bed with a sheet","Ask the family to hold the client down for the shift"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"restraints","kind":"mcq"}',
  'Try less restrictive measures and have the nurse stay with the client',
  'Try less restrictive measures and have the nurse stay with the client is the nurse''s action. Restraints are a last resort after less restrictive measures fail and an order is obtained. Incorrect: Restraints, a sheet, or family restraint skip safer options and the required order.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '7d3234435e97148121a2119789d3ef419f46d931f56d2689e5cc97bc90128edb',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'medication reconciliation',
  'safety-infection',
  'vignette',
  'A client takes warfarin at home. The admission list omits it. The client is about to receive a new order for ibuprofen.',
  'What does the nurse do?',
  '{"options":["Give the ibuprofen because it is a new order","Hold the ibuprofen, clarify the home warfarin, and reconcile the list before giving a conflicting drug","Document that the client probably stopped warfarin","Substitute aspirin"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"medication reconciliation","kind":"mcq"}',
  'Hold the ibuprofen, clarify the home warfarin, and reconcile the list before giving a conflicting drug',
  'Hold the ibuprofen, clarify the home warfarin, and reconcile the list before giving a conflicting drug is the nurse''s action. Reconciliation catches a high-risk drug that was left off the list before a bleeding interaction is given. Incorrect: Giving ibuprofen, assuming warfarin was stopped, or substituting aspirin adds bleeding risk.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'bd7c27174f6eca9aae78bc37022fbf5f3494c6a2515a1bd2609cce561815646a',
  'nclex-300-20261108-v1',
