) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'wrong-site time out',
  'safety-infection',
  'vignette',
  'The nurse is in the operating room. The consent says left knee, the surgical mark is on the right knee, and the client is already sedated.',
  'What does the nurse do?',
  '{"options":["Proceed because the client is sedated and the room is ready","Stop and reconcile the consent, the mark, and the site before incision","Ask the scrub person which knee looks more arthritic","Document the mismatch after the procedure"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"wrong-site time out","kind":"mcq"}',
  'Stop and reconcile the consent, the mark, and the site before incision',
  'Stop and reconcile the consent, the mark, and the site before incision is the nurse''s action. A site mismatch stops the procedure until consent and marking agree. Sedation does not waive the time-out. Incorrect: Proceeding, guessing from appearance, or documenting later allows a wrong-site surgery.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '1a1a97115b1cbd1c4d90480b46568d1ffa85b442c8a86c7b8ce8ca204fc6a0bf',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
