  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  3,
  'safety-infection',
  'safety-infection',
  'fire response',
  'safety-infection',
  'vignette',
  'The nurse discovers a fire in a client room. A client is in the bed. The alarm has not been pulled.',
  'Which action is first?',
  '{"options":["Search for the fire extinguisher before moving anyone","Rescue the client from the room","Close doors in the rest of the unit before rescuing","File an incident report"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"fire response","kind":"mcq"}',
  'Rescue the client from the room',
  'Rescue the client from the room is the nurse''s action. Rescue comes before alarm, confine, and extinguish when a person is in immediate danger. Incorrect: Looking for an extinguisher or writing a report first leaves the client in the fire.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '81e19810b79757845b31797331799c7c6798ae67273662fb16a013d2b903bdd2',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
