  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'needlestick',
  'safety-infection',
  'vignette',
  'A nurse is stuck by a needle used on a client with HIV and a detectable viral load. The stick just happened. Baseline labs are not drawn yet.',
  'What is the immediate plan?',
  '{"options":["Wash the site and start post-exposure prophylaxis without waiting for the nurse''s baseline result","Wait for the baseline test before any drug","Squeeze the wound and apply alcohol only","Skip prophylaxis because the source is known"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"needlestick","kind":"mcq"}',
  'Wash the site and start post-exposure prophylaxis without waiting for the nurse''s baseline result',
  'Wash the site and start post-exposure prophylaxis without waiting for the nurse''s baseline result is the nurse''s action. Occupational HIV prophylaxis is started as soon as possible. Baseline labs are drawn but do not delay the first doses. Incorrect: Waiting, alcohol alone, or skipping prophylaxis loses the early window.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '5fe946f1313215287da3332cdc86b2c7cc815a4516de1c11e6d0cedffb52a9a4',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
