  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  5,
  'safety-infection',
  'safety-infection',
  'suicide precautions environment',
  'safety-infection',
  'vignette',
  'A client is admitted after a suicide attempt and is on one-to-one observation. The room still has a trash-can liner, IV tubing, and a private bathroom with a lock.',
  'Which change is required?',
  '{"options":["Allow the private locked bathroom for dignity","Remove liners, tubing, and other hazards and keep the bathroom lock from isolating the client","Check the client every 30 minutes instead of one-to-one","Leave the tubing because an IV might be needed"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"suicide precautions environment","kind":"mcq"}',
  'Remove liners, tubing, and other hazards and keep the bathroom lock from isolating the client',
  'Remove liners, tubing, and other hazards and keep the bathroom lock from isolating the client is the nurse''s action. Observation fails if the room still contains means and a lockable space. Incorrect: A locked bathroom, stretching the observation interval, or leaving tubing keeps lethal means available.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '1c432069c40c5b2ec8cee2bfbba73184d28b1541dc9ee4e7587cb8d71be93554',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
