  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'charge nurse and a new fever',
  'management-of-care',
  'vignette',
  'During rounds the charge nurse learns one client has a new temperature of 39 C and a heart rate of 130. Three other clients are stable and waiting for discharge papers.',
  'Which action does the charge nurse take first?',
  '{"options":["See the client with fever and tachycardia","Delegate the discharge papers","Finish a supply count","Call the stable clients'' families"],"clientNeedsCategory":"Management of Care","blueprintTopic":"charge nurse and a new fever","kind":"mcq"}',
  'See the client with fever and tachycardia',
  'See the client with fever and tachycardia is the nurse''s action. A new fever with tachycardia may be sepsis and is assessed before paperwork. Incorrect: Discharge papers, a supply count, and family calls are not the unstable client.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '4cfcc0d02d7bc71436c2d649388770796a3a7ef37b5b3ee91a65413030d93a66',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
