) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  5,
  'management-of-care',
  'management-of-care',
  'refusal of blood',
  'management-of-care',
  'vignette',
  'A capacitated client who is a Jehovah''s Witness is bleeding and refuses packed red cells. The client understands the risk of death. The surgeon asks the nurse to persuade the client to accept blood.',
  'Which response is appropriate?',
  '{"options":["Support the refusal and ask the surgeon about alternatives the client would accept","Tell the client the refusal is not allowed in this hospital","Hang the blood while the client is looking away","Ask the family to override the refusal"],"clientNeedsCategory":"Management of Care","blueprintTopic":"refusal of blood","kind":"mcq"}',
  'Support the refusal and ask the surgeon about alternatives the client would accept',
  'Support the refusal and ask the surgeon about alternatives the client would accept is the nurse''s action. A capacitated refusal of blood is honored. The nurse can help seek acceptable alternatives. Incorrect: Forcing blood, hiding the transfusion, or a family override ignores the client''s decision.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '5176e24177a832cb7efc66517e3a968c1065974f5704ec6663254c6795d1d622',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
