) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  3,
  'management-of-care',
  'management-of-care',
  'against medical advice form',
  'management-of-care',
  'vignette',
  'A capacitated client is leaving against advice. The client will not sign the form. The nurse is choosing the safest next action for this client right now.',
  'What does the nurse do?',
  '{"options":["Keep the client until the form is signed","Document the refusal to sign, the teaching, and the departure","Refuse to give any discharge instructions","Call security to block the exit"],"clientNeedsCategory":"Management of Care","blueprintTopic":"against medical advice form","kind":"mcq"}',
  'Document the refusal to sign, the teaching, and the departure',
  'Document the refusal to sign, the teaching, and the departure is the nurse''s action. The form is evidence, not a requirement that traps the client. The nurse still documents and teaches. Incorrect: Holding the client, withholding instructions, or blocking the door is not how a capacitated departure works.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'df340c4ca5e4d618422426482c4c0cd9572a4dd02d73e4caeacf66902bc24040',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
