  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'scope of a phone order',
  'management-of-care',
  'vignette',
  'A provider gives a telephone order for morphine in milligrams but does not state the route. The nurse reads the order back without the route and the provider says yes.',
  'Which action is safe?',
  '{"options":["Write the route the unit usually uses","Do not give the drug until the route is stated and read back","Ask another nurse to choose the route","Give it orally because that is safest"],"clientNeedsCategory":"Management of Care","blueprintTopic":"scope of a phone order","kind":"mcq"}',
  'Do not give the drug until the route is stated and read back',
  'Do not give the drug until the route is stated and read back is the nurse''s action. A telephone order needs drug, dose, and route read back. A usual route is not an order. Incorrect: Guessing the route or choosing oral without an order is a medication error.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'cadb4e7218b9eef1d942ee4bbcedaecf214108cdd9c4812141c19b35a3e27a3c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
