  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'management-of-care',
  4,
  'management-of-care',
  'management-of-care',
  'visitor and infection',
  'management-of-care',
  'vignette',
  'A visitor with a draining wound on the hand wants to hold a newborn. The visitor will not cover the wound.',
  'What does the nurse do?',
  '{"options":["Allow the visit because family bonding comes first","Stop the visit until the wound is covered or the visitor leaves the nursery area","Give the visitor the baby and document the wound","Ask the visitor to use only one hand"],"clientNeedsCategory":"Management of Care","blueprintTopic":"visitor and infection","kind":"mcq"}',
  'Stop the visit until the wound is covered or the visitor leaves the nursery area',
  'Stop the visit until the wound is covered or the visitor leaves the nursery area is the nurse''s action. An uncovered draining wound is an infection risk to a newborn. Bonding does not override that. Incorrect: Allowing the hold or a one-hand compromise still exposes the infant.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'b17ef979c237dbaf70d5553bb138d4016ff03d23f4a2b306baea3b36b2143357',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
