) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  5,
  'safety-infection',
  'safety-infection',
  'protective environment',
  'safety-infection',
  'vignette',
  'A client has severe neutropenia after chemotherapy. A roommate with a cough is being admitted to the same double room.',
  'Which assignment does the nurse challenge?',
  '{"options":["Place the coughing client in a different room","Keep them together to save a private room","Turn off the neutropenic client''s positive-pressure ventilation","Allow fresh flowers in the neutropenic room"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"protective environment","kind":"mcq"}',
  'Place the coughing client in a different room',
  'Place the coughing client in a different room is the nurse''s action. A neutropenic client is protected from people with infections. A coughing roommate is the wrong assignment. Incorrect: Sharing the room, stopping protective airflow, or adding flowers increases infection risk.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '66e5a441af2dbe8fe6d444c5996a2f7f11e2e92d0d1452649e1985cff3a28aec',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'latex allergy',
  'safety-infection',
  'vignette',
  'A client reports a latex allergy with past lip swelling after a dental dam. The client is going to surgery.',
  'Which preparation is required?',
  '{"options":["Use latex-free gloves and equipment and notify the operating room","Use powdered latex gloves because powder reduces allergy","Schedule the client after all latex cases without cleaning the room","Document the allergy and take no other step"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"latex allergy","kind":"mcq"}',
  'Use latex-free gloves and equipment and notify the operating room',
  'Use latex-free gloves and equipment and notify the operating room is the nurse''s action. A systemic latex history means latex-free supplies and a notified team. Incorrect: Powdered latex, an uncleaned room, or documentation alone leaves exposure in place.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'af160e6360a34a905b06d9d966d592ac50ad6d08cbf5a90c6afd48220da35685',
  'nclex-300-20261108-v1',
  'pending',
  false,
