  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'radiation implant',
  'safety-infection',
  'vignette',
  'A client has a sealed cervical radiation implant. The nurse is organizing care and visitors.',
  'Which plan is appropriate?',
  '{"options":["Limit time near the client, keep distance, and use shielding as directed","Encourage children to sit on the bed","Assign a pregnant nurse for the full shift","Leave the implant in a shared bathroom if it dislodges"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"radiation implant","kind":"mcq"}',
  'Limit time near the client, keep distance, and use shielding as directed',
  'Limit time near the client, keep distance, and use shielding as directed is the nurse''s action. Time, distance, and shielding reduce exposure. Children and pregnant staff are not placed close. Incorrect: Bedside visits by children, a pregnant nurse for the shift, or a loose implant in a bathroom spread radiation.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'b1ead7999cc5be87599123a83ba884021904143a2a0c6b5cbdd4d5f8d47c07e4',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
