) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'chemotherapy spill',
  'safety-infection',
  'vignette',
  'A small puddle of IV chemotherapy is on the floor. The nurse is the first person there. The nurse is choosing the safest next action for this client right now.',
  'What is the first action?',
  '{"options":["Wipe it with a dry tissue and throw it in the regular trash","Keep people away and use the chemo spill kit","Mop it into the sink","Cover it with a client blanket"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"chemotherapy spill","kind":"mcq"}',
  'Keep people away and use the chemo spill kit',
  'Keep people away and use the chemo spill kit is the nurse''s action. A chemo spill is contained with the designated kit, not household cleanup. Incorrect: A tissue, a sink, or a blanket spreads the drug and exposes skin.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '195e108512ca980712cb742f1c8914dbfdfdc7d8fcfec15f55cb86e8658ab082',
  'nclex-300-20261108-v1',
