) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'restraint order renewal',
  'safety-infection',
  'vignette',
  'Bilateral wrist restraints were applied at 0200 with an order. It is now 1000 and the client is calm. The nurse is evaluating the restraints.',
  'Which action is appropriate?',
  '{"options":["Leave them on until tomorrow''s order","Remove them if the client no longer needs them and get a new order before any reapplication","Tie them tighter so the client stays calm","Document that restraints do not need reassessment"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"restraint order renewal","kind":"mcq"}',
  'Remove them if the client no longer needs them and get a new order before any reapplication',
  'Remove them if the client no longer needs them and get a new order before any reapplication is the nurse''s action. Restraints are removed as soon as the behavior allows. A new order is required to restart them. Incorrect: Leaving them all day, tightening them, or skipping reassessment continues an unnecessary restraint.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '7ceeb5bd00598953964d5d2618511b40db5ab7c9fa899c38e4485ed9d7a9d0ce',
  'nclex-300-20261108-v1',
  'pending',
