) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  5,
  'basic-care-comfort',
  'basic-care-comfort',
  'dysphagia diet',
  'basic-care-comfort',
  'vignette',
  'A client with a stroke coughs when given thin water. The speech therapist has not cleared a diet. The tray has regular liquids.',
  'Which feeding decision does the nurse make?',
  '{"options":["Give thin water slowly","Keep the client NPO for oral intake until a swallow evaluation","Start a regular diet because the client is hungry","Give the liquids through a straw"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"dysphagia diet","kind":"mcq"}',
  'Keep the client NPO for oral intake until a swallow evaluation',
  'Keep the client NPO for oral intake until a swallow evaluation is the nurse''s action. Coughing with thin liquids is aspiration risk. Oral intake waits for a swallow study. Incorrect: Slow thin water, a regular diet, or a straw still sends liquid toward the airway.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '388188adc5d47396a652a45d0acd98da48f58d54270711b06af0da373e902418',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
