) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  4,
  'basic-care-comfort',
  'basic-care-comfort',
  'pressure injury turn',
  'basic-care-comfort',
  'vignette',
  'A client with a stage 2 pressure injury on the sacrum is supine. The injury is from moisture and pressure.',
  'Which repositioning plan is appropriate?',
  '{"options":["Turn at least every 2 hours and keep pressure off the sacrum","Leave the client supine so the dressing is not disturbed","Massage the reddened sacrum","Sit the client in a chair for 6 hours without a shift"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"pressure injury turn","kind":"mcq"}',
  'Turn at least every 2 hours and keep pressure off the sacrum',
  'Turn at least every 2 hours and keep pressure off the sacrum is the nurse''s action. Pressure is relieved by turning and offloading. The dressing is not a reason to stay on the wound. Incorrect: Staying supine, massage, or a long unrelieved sit worsens the injury.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'd82d65eb44eca31d964928051db2a8a914b3d810f15595a61a0f009380cb421c',
  'nclex-300-20261108-v1',
  'pending',
