) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  4,
  'basic-care-comfort',
  'basic-care-comfort',
  'oxygen device',
  'basic-care-comfort',
  'vignette',
  'A client with chronic carbon dioxide retention is somnolent after a family member turned the nasal cannula from 2 L to 8 L. The respiratory rate is 8.',
  'What does the nurse do first?',
  '{"options":["Leave the oxygen at 8 L because more is better","Reduce the flow toward the prescribed rate and stimulate the client, and support breathing if it does not improve","Turn the oxygen off completely and leave the room","Give a sedative for the sleepiness"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"oxygen device","kind":"mcq"}',
  'Reduce the flow toward the prescribed rate and stimulate the client, and support breathing if it does not improve',
  'Reduce the flow toward the prescribed rate and stimulate the client, and support breathing if it does not improve is the nurse''s action. Too much oxygen can depress the drive in a retainer. The nurse corrects the flow and stays for the breathing. Incorrect: Leaving 8 L, walking away with oxygen off, or adding a sedative worsens hypoventilation.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '4ecb9353c262f79cdbb4f6f9a37ad5b2fb2ced4526a900fce9cdddf599aa6bb5',
  'nclex-300-20261108-v1',
  'pending',
  false,
