) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  4,
  'basic-care-comfort',
  'basic-care-comfort',
  'tube feeding residual',
  'basic-care-comfort',
  'vignette',
  'A client receiving continuous tube feeding has a gastric residual of 400 mL and new abdominal distension and nausea. The last residual was 40 mL.',
  'Which action does the nurse take?',
  '{"options":["Increase the feeding rate","Stop the feeding and notify the provider about the high residual and symptoms","Discard the residual and restart at the same rate without telling anyone","Lay the client flat and continue the feeding"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"tube feeding residual","kind":"mcq"}',
  'Stop the feeding and notify the provider about the high residual and symptoms',
  'Stop the feeding and notify the provider about the high residual and symptoms is the nurse''s action. A jump in residual with distension and nausea means the feeding is not moving. It is held and reported. Incorrect: Speeding the feeding, restarting quietly, or lying flat increases aspiration risk.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '30151d6ee91f4ebc5c061e8fa29f5b450ef421bb37e20f698287d1ae2e5a10bb',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
