  gen_random_uuid()::text,
  'nursing',
  'basic-care-comfort',
  3,
  'basic-care-comfort',
  'basic-care-comfort',
  'ostomy pouch',
  'basic-care-comfort',
  'vignette',
  'A new colostomy pouch is leaking stool onto the skin. The stoma is pink. The skin is red where stool has sat.',
  'What does the nurse do?',
  '{"options":["Leave the pouch so the client can learn the leak","Change the pouch, clean the skin, and resize the opening to protect the skin","Cover the leak with tape only","Irrigate the stoma with tap water under pressure"],"clientNeedsCategory":"Basic Care and Comfort","blueprintTopic":"ostomy pouch","kind":"mcq"}',
  'Change the pouch, clean the skin, and resize the opening to protect the skin',
  'Change the pouch, clean the skin, and resize the opening to protect the skin is the nurse''s action. Stool on skin causes breakdown. A leaking pouch is changed and fitted. Incorrect: Leaving it, tape alone, or a forceful irrigation does not protect the skin.',
  '["nclex","NCLEX-RN-2026","basic-care-comfort","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'b787fef5c172c6c19249db38729cb9916490d16102165d06c83a65685cfb9e62',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
