) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'chest tube disconnection',
  'reduction-risk',
  'vignette',
  'A client''s chest tube disconnects from the drainage system. The tube is still in the chest. The client is breathing and anxious.',
  'What does the nurse do first?',
  '{"options":["Clamp the tube and leave for the provider","Place the open end in sterile water to make a water seal while calling for help","Reconnect it to the dirty end on the floor","Pull the tube out"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"chest tube disconnection","kind":"mcq"}',
  'Place the open end in sterile water to make a water seal while calling for help',
  'Place the open end in sterile water to make a water seal while calling for help is the nurse''s action. An open chest tube can let air in. A temporary water seal restores a one-way system. Incorrect: Clamping, a dirty reconnect, or pulling the tube creates a worse pneumothorax or infection.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'dd8c69e279fdc74e94b242430bcb4481bd6d25f265ee7ca6b1a0c896a3c47c88',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
