) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'transfusion reaction',
  'reduction-risk',
  'vignette',
  'Ten minutes into a red-cell transfusion the client has fever, back pain, and dark urine. Blood pressure is falling.',
  'Which action is first?',
  '{"options":["Slow the rate and give diphenhydramine","Stop the transfusion and keep the vein open with normal saline","Speed the unit so it finishes","Start the next unit"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"transfusion reaction","kind":"mcq"}',
  'Stop the transfusion and keep the vein open with normal saline',
  'Stop the transfusion and keep the vein open with normal saline is the nurse''s action. Fever, pain, dark urine, and hypotension during a transfusion are a hemolytic reaction until proved otherwise. The unit stops. Incorrect: Slowing, speeding, or hanging another unit keeps incompatible blood running.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '45d72f218da4c141f08111f82a4af49c3157857a81a28d43723ef13aabb5f26c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
