) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  4,
  'reduction-risk',
  'reduction-risk',
  'postoperative bleeding',
  'reduction-risk',
  'vignette',
  'One hour after abdominal surgery the dressing is saturated and blood is pooling under the client. Heart rate is 122 and blood pressure is 88/54.',
  'What is the nurse''s first action?',
  '{"options":["Reinforce the dressing and reassess in an hour","Stay with the client, apply pressure as appropriate, and activate help for bleeding and shock","Have the client walk to reduce clots","Give the oral pain pill and wait"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"postoperative bleeding","kind":"mcq"}',
  'Stay with the client, apply pressure as appropriate, and activate help for bleeding and shock',
  'Stay with the client, apply pressure as appropriate, and activate help for bleeding and shock is the nurse''s action. Saturated dressings with tachycardia and hypotension are hemorrhage. The nurse stays and gets help. Incorrect: Waiting an hour, walking, or a pain pill delays resuscitation.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '56e659f31780a43266e6607d71c21e1288e303761e3e39a384956b2cb8fe60e4',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
