  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'wound evisceration',
  'reduction-risk',
  'vignette',
  'A client coughs and the abdominal incision opens. Bowel is visible on the abdomen. The nurse is choosing the safest next action for this client right now.',
  'Which action does the nurse take?',
  '{"options":["Push the bowel back in","Cover the bowel with sterile saline-moistened gauze and keep the client supine with the knees bent while calling the surgeon","Sit the client up and give a drink","Apply a dry dressing and send the client to the bathroom"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"wound evisceration","kind":"mcq"}',
  'Cover the bowel with sterile saline-moistened gauze and keep the client supine with the knees bent while calling the surgeon',
  'Cover the bowel with sterile saline-moistened gauze and keep the client supine with the knees bent while calling the surgeon is the nurse''s action. Exposed bowel is kept moist and the client is positioned to reduce strain. The surgeon is called. Incorrect: Pushing bowel back, sitting the client up, or a dry dressing and walking harms the bowel.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '386ab3c12baa86dd0a122bebb9364abe688fc4feec16e2d19a1700def879deb6',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'reduction-risk',
  5,
  'reduction-risk',
  'reduction-risk',
  'cast and compartment',
  'reduction-risk',
  'vignette',
  'A client in a new leg cast has pain out of proportion, pain when the toes are stretched, and a tight cast. Toes are still warm.',
  'What does the nurse do?',
  '{"options":["Reassure the client that warm toes rule out a problem","Notify the provider immediately for possible compartment syndrome and prepare to loosen the cast","Elevate the leg above the heart and recheck in 4 hours","Give the next dose of opioid and wait"],"clientNeedsCategory":"Reduction of Risk Potential","blueprintTopic":"cast and compartment","kind":"mcq"}',
  'Notify the provider immediately for possible compartment syndrome and prepare to loosen the cast',
  'Notify the provider immediately for possible compartment syndrome and prepare to loosen the cast is the nurse''s action. Pain out of proportion and pain on stretch are compartment syndrome even when pulses and warmth remain. Incorrect: Reassurance, a long delay, or more opioid alone loses muscle.',
  '["nclex","NCLEX-RN-2026","reduction-risk","nclex-300-20261108-v1"]',
  '[{"label":"The Joint Commission. National Patient Safety Goals. 2026","url":"https://www.jointcommission.org/standards/national-patient-safety-goals/"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'e9242ea4ad6e8e40dee373fe51b7332c0d5cbbb8a1cd8d593314dedb9270655d',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
