  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'psychosocial',
  4,
  'psychosocial',
  'psychosocial',
  'suicide ask directly',
  'psychosocial',
  'vignette',
  'A client says, I might be better off if I did not wake up. The client has no prior plan documented.',
  'Which question does the nurse ask next?',
  '{"options":["Are you thinking about killing yourself, and do you have a plan?","Why would you say something so upsetting?","You do not mean that, do you?","Let us talk about the weather until this passes"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"suicide ask directly","kind":"mcq"}',
  'Are you thinking about killing yourself, and do you have a plan?',
  'Are you thinking about killing yourself, and do you have a plan? is the nurse''s action. Passive death wishes are followed by a direct question about intent and a plan. Incorrect: Criticism, a leading denial, or changing the subject misses the risk.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '50cd344288bfda9f362d26949de6cd279e66dc854eb6238a94a00c5bbcd8007c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'psychosocial',
  4,
  'psychosocial',
  'psychosocial',
  'panic breathing',
  'psychosocial',
  'vignette',
  'A client is having a panic attack, breathing 36 times a minute, and saying they are about to die. Oxygen saturation is 99 percent.',
  'Which action does the nurse take?',
  '{"options":["Tell the client to calm down","Stay with the client and coach slow breaths","Leave to find a pamphlet","Give a detailed lecture on anxiety physiology"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"panic breathing","kind":"mcq"}',
  'Stay with the client and coach slow breaths',
  'Stay with the client and coach slow breaths is the nurse''s action. Presence and slower breathing reduce the attack. The saturation shows this is not hypoxia. Incorrect: Ordering calm, leaving, or a lecture does not help in the moment.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '52d4ec4296f1781515bb2504cc1f6d6addbc9684422045f0ad1d9798da8ac426',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
