) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'psychosocial',
  4,
  'psychosocial',
  'psychosocial',
  'hearing voices',
  'psychosocial',
  'vignette',
  'A client with schizophrenia is frightened by voices that say the food is poisoned. The client has not eaten today.',
  'Which response is therapeutic?',
  '{"options":["The voices are lying and you are being difficult","I do not hear those voices. I will stay with you, and we can look at the sealed tray together","Eat it or you will be discharged","The poison is real and I will throw the tray away"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"hearing voices","kind":"mcq"}',
  'I do not hear those voices. I will stay with you, and we can look at the sealed tray together',
  'I do not hear those voices. I will stay with you, and we can look at the sealed tray together is the nurse''s action. The nurse does not argue the hallucination or agree with it. Staying and offering a sealed tray addresses fear and intake. Incorrect: Calling the client difficult, threatening discharge, or agreeing that the food is poisoned does not help.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '56158a92bef6fecbf701351a7698fd10617ee14d7f987dd41e27572a8391c770',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
