) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'psychosocial',
  5,
  'psychosocial',
  'psychosocial',
  'alcohol withdrawal',
  'psychosocial',
  'vignette',
  'A client who drinks daily is tremulous, tachycardic, and diaphoretic 16 hours after the last drink. The client is oriented.',
  'Which risk does the nurse prepare for?',
  '{"options":["A self-limited tremor that needs no medication","Progression to seizure or delirium, so benzodiazepines are given per protocol","Immediate discharge to keep the unit quiet","Restraint without medication"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"alcohol withdrawal","kind":"mcq"}',
  'Progression to seizure or delirium, so benzodiazepines are given per protocol',
  'Progression to seizure or delirium, so benzodiazepines are given per protocol is the nurse''s action. Early withdrawal is treated with benzodiazepines so it does not become seizures or delirium. Incorrect: Watching only, discharging, or restraining without treatment leaves the seizure risk.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '5e2a63c2ed5b7666d49d87f648c908aabf6abd2a99b674c2b6397e1bce0b2bce',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
