  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'psychosocial',
  4,
  'psychosocial',
  'psychosocial',
  'grief versus depression',
  'psychosocial',
  'vignette',
  'Two months after a spouse''s death, a client cries when looking at photos but is eating, working, and has no wish to die.',
  'Which interpretation is most appropriate?',
  '{"options":["This is still consistent with grief","This is major depression that must be treated before any listening","The client should be told to stop crying","The client is psychotic"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"grief versus depression","kind":"mcq"}',
  'This is still consistent with grief',
  'This is still consistent with grief is the nurse''s action. Crying with preserved function and no suicidal wish two months later can be grief. The nurse listens and screens, but does not label it psychosis. Incorrect: Forcing treatment before listening, banning tears, or calling it psychosis misreads grief.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '99f0c5269992b190790e0f87793cebaef70d2c3613a994a44062561a104ec8a1',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
