) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'health-promotion',
  4,
  'health-promotion',
  'health-promotion',
  'newborn vaccines',
  'health-promotion',
  'vignette',
  'A healthy newborn is going home. The parent asks which vaccine is given before discharge in the United States.',
  'Which vaccine is given?',
  '{"options":["Hepatitis B","Live measles vaccine","Yearly influenza injection today as the only vaccine","Human papillomavirus vaccine"],"clientNeedsCategory":"Health Promotion and Maintenance","blueprintTopic":"newborn vaccines","kind":"mcq"}',
  'Hepatitis B',
  'Hepatitis B is the nurse''s action. A birth dose of hepatitis B is given before discharge. Measles and HPV are not newborn vaccines. Incorrect: Measles, influenza as the only shot, and HPV are the wrong timing.',
  '["nclex","NCLEX-RN-2026","health-promotion","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Adult immunization schedule. CDC 2026","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/adult-notes.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '4a523fc63fd1e9667b7761bdafe0e068814ae4a030995a915974f985afee816e',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
