) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'health-promotion',
  3,
  'health-promotion',
  'health-promotion',
  'car seat',
  'health-promotion',
  'vignette',
  'Parents of a term newborn are being discharged. They plan to hold the baby in the front seat on the way home.',
  'Which teaching is correct?',
  '{"options":["Use a rear-facing car seat in the back seat","A front-seat lap hold is fine for the first ride","The baby may ride in a borrowed forward-facing seat today","A car seat is optional under 1 month"],"clientNeedsCategory":"Health Promotion and Maintenance","blueprintTopic":"car seat","kind":"mcq"}',
  'Use a rear-facing car seat in the back seat',
  'Use a rear-facing car seat in the back seat is the nurse''s action. Newborns ride rear-facing in the back seat, not on a lap in front. Incorrect: A lap hold, an immediate forward-facing seat, or skipping the seat is unsafe.',
  '["nclex","NCLEX-RN-2026","health-promotion","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'a7990b0f7611ca8399f0bae30b19200f82f05cbe1aaa72c547739c226092d4d4',
  'nclex-300-20261108-v1',
  'pending',
  false,
