) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'health-promotion',
  4,
  'health-promotion',
  'health-promotion',
  'safe sleep',
  'health-promotion',
  'vignette',
  'A parent plans to put the newborn prone on a soft pillow with a blanket because the baby sleeps longer that way.',
  'Which teaching does the nurse give?',
  '{"options":["Place the baby supine on a firm flat surface with no loose bedding","Prone sleep is safer if a monitor is on","A pillow prevents flat head and is required","The parent bed with a heavy blanket is the safest place"],"clientNeedsCategory":"Health Promotion and Maintenance","blueprintTopic":"safe sleep","kind":"mcq"}',
  'Place the baby supine on a firm flat surface with no loose bedding',
  'Place the baby supine on a firm flat surface with no loose bedding is the nurse''s action. Supine on a firm surface without soft bedding lowers sudden infant death risk. Incorrect: Prone sleep, a pillow, or an adult bed with a heavy blanket raises that risk.',
  '["nclex","NCLEX-RN-2026","health-promotion","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'cc6cefd40cc72fca03e65db70b987b09e640872c04b94a04033d401d1791472b',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
