  gen_random_uuid()::text,
  'nursing',
  'health-promotion',
  3,
  'health-promotion',
  'health-promotion',
  'colon screening',
  'health-promotion',
  'vignette',
  'A 46-year-old client at average risk asks when colorectal screening should start. The nurse is choosing the safest next action for this client right now.',
  'Which answer is consistent with current U.S. guidance?',
  '{"options":["Start at 45","Wait until 60","Start only after symptoms","Screening is not used in adults"],"clientNeedsCategory":"Health Promotion and Maintenance","blueprintTopic":"colon screening","kind":"mcq"}',
  'Start at 45',
  'Start at 45 is the nurse''s action. Average-risk colorectal screening now starts at 45. Incorrect: Waiting until 60, waiting for symptoms, or skipping screening misses the recommendation.',
  '["nclex","NCLEX-RN-2026","health-promotion","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Adult immunization schedule. CDC 2026","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/adult-notes.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '87938ad14f4b61a469aba4174725672a76ccd8069adc54a0c33121646f46e05c',
  'nclex-300-20261108-v1',
