  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'health-promotion',
  4,
  'health-promotion',
  'health-promotion',
  'prenatal folic acid',
  'health-promotion',
  'vignette',
  'A client plans to conceive in two months and had a prior pregnancy affected by a neural-tube defect. The current multivitamin has 0.4 mg of folic acid.',
  'Which folic acid plan does the nurse reinforce?',
  '{"options":["4 mg daily, started before conception","Stay at 0.4 mg","Start 4 mg only after week 12","Replace folic acid with vitamin A megadoses"],"clientNeedsCategory":"Health Promotion and Maintenance","blueprintTopic":"prenatal folic acid","kind":"mcq"}',
  '4 mg daily, started before conception',
  '4 mg daily, started before conception is the nurse''s action. A prior neural-tube defect calls for a higher folic acid dose before conception, not the routine 0.4 mg. Incorrect: Staying at 0.4 mg, starting late, or megadose vitamin A is the wrong plan.',
  '["nclex","NCLEX-RN-2026","health-promotion","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Adult immunization schedule. CDC 2026","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/adult-notes.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '6a67be3ca495eb614c7e80e4a59dedeaa9b373579cb0df3819900413d2701eb3',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
