  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  4,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'insulin mixing',
  'pharmacology-nursing',
  'vignette',
  'A nurse is drawing NPH and regular insulin in one syringe. The nurse is choosing the safest next action for this client right now.',
  'Which sequence is correct?',
  '{"options":["Draw up the cloudy insulin first","Inject air into cloudy, inject air into clear, draw clear, then draw cloudy","Shake the NPH hard, then draw it alone into the regular vial","Mix them in the vial of regular insulin"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"insulin mixing","kind":"mcq"}',
  'Inject air into cloudy, inject air into clear, draw clear, then draw cloudy',
  'Inject air into cloudy, inject air into clear, draw clear, then draw cloudy is the nurse''s action. Clear regular is drawn before cloudy NPH so the NPH vial is not contaminated with regular in the wrong direction. The usual air order is cloudy then clear. Incorrect: Drawing cloudy first into the syringe, shaking, or mixing inside the regular vial contaminates the vials.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '868288ae606d3d6dd5d110cb0ecac7a432b012c98c2fef06a7b5028c514462de',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  5,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'digoxin hold',
  'pharmacology-nursing',
  'vignette',
  'A client''s apical pulse is 52 beats per minute. Digoxin is due. The client is nauseated and sees yellow halos.',
  'What does the nurse do?',
  '{"options":["Give the digoxin with food","Hold the digoxin and notify the provider","Give half the dose","Give the dose and recheck the pulse tomorrow"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"digoxin hold","kind":"mcq"}',
  'Hold the digoxin and notify the provider',
  'Hold the digoxin and notify the provider is the nurse''s action. A slow apical rate plus nausea and visual halos is digoxin toxicity. The dose is held. Incorrect: Giving it, halving it, or waiting until tomorrow continues toxicity.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '0230110ddbfb521ce029ef492e7f90372ca444759c42c97f654f038293fb986b',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  4,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'potassium and a diuretic',
  'pharmacology-nursing',
  'vignette',
  'A client is due for IV furosemide. The morning potassium is 3.0 mEq/L. The client has muscle cramps.',
  'Which action does the nurse take?',
  '{"options":["Give the furosemide to treat fluid status first","Hold the furosemide and notify the provider about the potassium","Give the furosemide with orange juice as a substitute for replacement","Double the dose because the potassium is low"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"potassium and a diuretic","kind":"mcq"}',
  'Hold the furosemide and notify the provider about the potassium',
  'Hold the furosemide and notify the provider about the potassium is the nurse''s action. Loop diuretics lower potassium further. A potassium of 3.0 with cramps is reported and the dose is held. Incorrect: Giving or doubling the diuretic, or using juice as the only replacement, worsens hypokalemia.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '486a6d147a74c538bff66b89070b10575a53b8da8b504278a3c21994224c270c',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
  "generationVersion", "reviewStatus", "active", "qaPassed", "manual_correction",
  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  4,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'vancomycin rate',
  'pharmacology-nursing',
  'vignette',
  'A client starts IV vancomycin and develops flushing and itching of the face and neck during a fast infusion. Blood pressure is stable.',
  'What does the nurse do?',
  '{"options":["Speed the infusion so it ends sooner","Stop or slow the infusion and treat the red-man reaction per protocol","Ignore it because the blood pressure is normal","Give the next dose as an IV push"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"vancomycin rate","kind":"mcq"}',
  'Stop or slow the infusion and treat the red-man reaction per protocol',
  'Stop or slow the infusion and treat the red-man reaction per protocol is the nurse''s action. Flushing during a fast vancomycin infusion is an infusion reaction. The rate is slowed. Incorrect: Speeding it, ignoring it, or pushing the next dose worsens the reaction.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'ec1c9a88e34f8b5c173a882ee8b97fa9d22e370650c43b57a8a0ea45fb608f21',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
