) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'pharmacology-nursing',
  5,
  'pharmacology-nursing',
  'pharmacology-nursing',
  'opioid and respiratory rate',
  'pharmacology-nursing',
  'vignette',
  'A postoperative client received IV morphine 20 minutes ago. The respiratory rate is 7 and the client is hard to arouse.',
  'Which drug does the nurse prepare?',
  '{"options":["Flumazenil","Naloxone","Vitamin K","Protamine"],"clientNeedsCategory":"Pharmacological and Parenteral Therapies","blueprintTopic":"opioid and respiratory rate","kind":"mcq"}',
  'Naloxone',
  'Naloxone is the nurse''s action. A slow rate and hard arousal after morphine is opioid toxicity. Naloxone reverses it. Incorrect: Flumazenil is for benzodiazepines, vitamin K for warfarin, and protamine for heparin.',
  '["nclex","NCLEX-RN-2026","pharmacology-nursing","nclex-300-20261108-v1"]',
  '[{"label":"Institute for Safe Medication Practices. Targeted Medication Safety Best Practices. ISMP 2024","url":"https://www.ismp.org/guidelines/best-practices-hospitals"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '88c2204bc2f27a9f11b2ae5d1297339157bd4ffd52a37bba1afcef09ceb93851',
  'nclex-300-20261108-v1',
  'pending',
  false,
