) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  5,
  'physiological-adaptation',
  'physiological-adaptation',
  'anaphylaxis',
  'physiological-adaptation',
  'vignette',
  'A client receiving an IV antibiotic develops hives, wheezing, and a blood pressure of 80/40.',
  'Which drug does the nurse give first?',
  '{"options":["Diphenhydramine only","Intramuscular epinephrine","An oral steroid","A saline flush of the antibiotic line"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"anaphylaxis","kind":"mcq"}',
  'Intramuscular epinephrine',
  'Intramuscular epinephrine is the nurse''s action. Wheezing and shock with hives is anaphylaxis. Epinephrine is first. Incorrect: An antihistamine or steroid alone, or flushing more antibiotic, does not reverse shock.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '4f0f08291443b5c1631c35c5f8dfbe2bccf37e5550b03a80f272a1fcd06b00b1',
  'nclex-300-20261108-v1',
  'pending',
