) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  4,
  'physiological-adaptation',
  'physiological-adaptation',
  'chest pain MONA trap',
  'physiological-adaptation',
  'vignette',
  'A client has crushing chest pain and oxygen saturation of 98 percent on room air. Aspirin is ordered and has not been given. Oxygen is not ordered.',
  'Which action is appropriate?',
  '{"options":["Apply a nonrebreather at 15 L because every chest pain gets oxygen","Give the aspirin if there is no allergy, and do not add unneeded high-flow oxygen","Withhold aspirin until after a meal","Have the client walk to reduce the pain"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"chest pain MONA trap","kind":"mcq"}',
  'Give the aspirin if there is no allergy, and do not add unneeded high-flow oxygen',
  'Give the aspirin if there is no allergy, and do not add unneeded high-flow oxygen is the nurse''s action. Aspirin is given early for suspected acute coronary syndrome. Oxygen is not automatic when saturation is already normal. Incorrect: High-flow oxygen, delaying aspirin, or walking the client is not the early treatment.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '916e1b7378a54696b57ea79fb6afa66c8d73bc166e372f217705fd9359a082e8',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
INSERT INTO "QuestionBankItem" (
  "id", "fieldId", "subjectId", "difficulty", "topicCategory", "blueprintDomain",
  "blueprintTopic", "clientNeeds", "itemType", "scenario", "question", "options",
  "correctAnswer", "explanation", "tags", "references", "source", "contentHash",
