  "createdAt", "updatedAt"
) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  5,
  'physiological-adaptation',
  'physiological-adaptation',
  'stroke time',
  'physiological-adaptation',
  'vignette',
  'A client has a sudden right arm drift and slurred speech that the spouse says started 40 minutes ago. Glucose is 110 mg/dL.',
  'What does the nurse do first?',
  '{"options":["Give the client water to see if the speech clears","Activate a stroke response and keep the client NPO","Send the client for a routine clinic visit tomorrow","Lower the head of the bed to flat and start enteral feeding"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"stroke time","kind":"mcq"}',
  'Activate a stroke response and keep the client NPO',
  'Activate a stroke response and keep the client NPO is the nurse''s action. Sudden deficits within a treatment window need an immediate stroke pathway. Nothing is given by mouth until swallowing is safe. Incorrect: Water, a next-day visit, or feeding risks aspiration and misses the window.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '61fb00ac129d2191e3a401c5b37020c79a229203144d96f35dee19c3736a693e',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
