) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  5,
  'physiological-adaptation',
  'physiological-adaptation',
  'DKA potassium',
  'physiological-adaptation',
  'vignette',
  'A client in diabetic ketoacidosis has a glucose of 480 mg/dL and a pH of 7.15. The potassium result is not back. The electrocardiogram is normal. Insulin is ready.',
  'What does the nurse do about the insulin?',
  '{"options":["Start the insulin before the potassium is known","Hold the insulin until the potassium is known to be at least 3.3 mEq/L","Give bicarbonate as the only drug","Give a subcutaneous dose and discharge"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"DKA potassium","kind":"mcq"}',
  'Hold the insulin until the potassium is known to be at least 3.3 mEq/L',
  'Hold the insulin until the potassium is known to be at least 3.3 mEq/L is the nurse''s action. Insulin drives potassium into cells. It is not started until the nurse knows the potassium is not already low. Incorrect: Blind insulin, bicarbonate alone, or discharge is not how ketoacidosis is opened.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"American Diabetes Association. Standards of Care in Diabetes 2026. Diabetes Care 2026","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  '97f3f7275333b99c286fd0501b2780dcc0b1a63f377881cf665d5dfa48506746',
  'nclex-300-20261108-v1',
  'pending',
  false,
  false,
  true,
  NOW(),
  NOW()
);
