) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'physiological-adaptation',
  4,
  'physiological-adaptation',
  'physiological-adaptation',
  'pulmonary embolism',
  'physiological-adaptation',
  'vignette',
  'A postoperative client suddenly cannot breathe, has chest pain, and an oxygen saturation of 86 percent. The calf is swollen.',
  'Which action is first?',
  '{"options":["Have the client walk the clot out","Sit the client up, give oxygen, and notify the provider for a possible pulmonary embolism","Give a bronchodilator only","Lower the head of the bed and give fluids as the only step"],"clientNeedsCategory":"Physiological Adaptation","blueprintTopic":"pulmonary embolism","kind":"mcq"}',
  'Sit the client up, give oxygen, and notify the provider for a possible pulmonary embolism',
  'Sit the client up, give oxygen, and notify the provider for a possible pulmonary embolism is the nurse''s action. Sudden hypoxia, chest pain, and a swollen calf after surgery are embolism until proved otherwise. Oxygen and help come first. Incorrect: Walking, a bronchodilator alone, or fluids only do not treat the clot or the oxygen.',
  '["nclex","NCLEX-RN-2026","physiological-adaptation","nclex-300-20261108-v1"]',
  '[{"label":"American Heart Association. CPR and ECC guidelines. AHA 2025","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
  'generated',
  'c7e40f330c68a2b6321dedbf382048e281445d27794fdd7047f1c89cb60f2adb',
  'nclex-300-20261108-v1',
  'pending',
  false,
