  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'measles precautions',
  'safety-infection',
  'vignette',
  'A client is admitted with confirmed measles. The charge nurse is assigning the room and the protective equipment.',
  'Which precaution plan is appropriate?',
  '{"options":["airborne infection isolation and a respirator for staff","a surgical mask in a shared room","No precautions if the client is afebrile","A shared room with an immunocompromised roommate"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"measles precautions","kind":"mcq"}',
  'airborne infection isolation and a respirator for staff',
  'airborne infection isolation and a respirator for staff is the nurse''s action. measles has a specific transmission route, and the equipment has to match that route. Incorrect: The other plans use the wrong route or place a vulnerable roommate at risk.',
  '["nclex","NCLEX-RN-2026","safety-infection","nclex-300-20261108-v1"]',
  '[{"label":"CDC. Isolation Precautions and transmission-based precautions for healthcare. CDC 2024","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/index.html"},{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
