) VALUES (
  gen_random_uuid()::text,
  'nursing',
  'safety-infection',
  4,
  'safety-infection',
  'safety-infection',
  'MRSA in an open wound precautions',
  'safety-infection',
  'vignette',
  'A client is admitted with confirmed MRSA in an open wound. The charge nurse is assigning the room and the protective equipment.',
  'Which precaution plan is appropriate?',
  '{"options":["contact precautions with gown and gloves","a mask as the only addition","No precautions if the client is afebrile","A shared room with an immunocompromised roommate"],"clientNeedsCategory":"Safety and Infection Prevention and Control","blueprintTopic":"MRSA in an open wound precautions","kind":"mcq"}',
  'contact precautions with gown and gloves',
