  'vignette',
  'The nurse is dividing work. One task is a stable client who needs a urine specimen collected from a hat. An assistive person and an RN are available.',
  'Which statement is the correct assignment?',
  '{"options":["The assistive person may collect the specimen because the client is stable and the nurse remains accountable","The assistive person should start a blood transfusion","The assistive person may take the unstable client in the next bed too","The nurse does not need to follow up"],"clientNeedsCategory":"Management of Care","blueprintTopic":"delegate a stable client who needs a urine specim","kind":"mcq"}',
  'The assistive person may collect the specimen because the client is stable and the nurse remains accountable',
  'The assistive person may collect the specimen because the client is stable and the nurse remains accountable is the nurse''s action. Stable hygiene, ambulation already cleared, and collection tasks can be delegated. The nurse still assesses and follows up. Incorrect: Start a blood transfusion is a nursing judgment or an invasive or titrated therapy.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
