  'priority the hypotensive confused client',
  'management-of-care',
  'vignette',
  'Two call lights go on. One is a client with a blood pressure of 78/42 and new confusion. The other is a client asking for a blanket.',
  'Whom does the nurse see first?',
  '{"options":["The hypotensive confused client","A client asking for a blanket","Whichever light was pressed first","The client closest to the desk regardless of the symptom"],"clientNeedsCategory":"Management of Care","blueprintTopic":"priority the hypotensive confused client","kind":"mcq"}',
  'The hypotensive confused client',
  'The hypotensive confused client is the nurse''s action. The first client has a change that can threaten airway, breathing, circulation, or bleeding. Incorrect: Routine comfort and the order of the call light do not outrank that change.',
  '["nclex","NCLEX-RN-2026","management-of-care","nclex-300-20261108-v1"]',
