  'psychosocial',
  'What does the nurse do?',
  'psychosocial',
  'vignette',
  'A client with schizophrenia stops taking medicine because of a side effect and is becoming more paranoid.',
  'What does the nurse do?',
  '{"options":["Explore the side effect and involve the provider rather than shaming the client","Tell the client to get over it","Ask the roommate to decide","Wait until the next shift"],"clientNeedsCategory":"Psychosocial Integrity","blueprintTopic":"What does the nurse do?","kind":"mcq"}',
  'Explore the side effect and involve the provider rather than shaming the client',
  'Explore the side effect and involve the provider rather than shaming the client is the nurse''s action. The correct action removes the immediate risk or uses the right scope and precaution. Incorrect: Waiting, guessing, or handing the choice to a roommate leaves the client unsafe.',
  '["nclex","NCLEX-RN-2026","psychosocial","nclex-300-20261108-v1"]',
  '[{"label":"NCSBN. NCLEX-RN Test Plan, effective April 2026","url":"https://www.ncsbn.org/public-files/2026_RN_Test-Plan_English-F.pdf"}]'::jsonb,
